parameters.jsCode:
const rows = $input.all().map(item => item.json);

// ============================================================
// 1. 获取前端指定的 analysis_run_id
// ============================================================

const webhook = $("Webhook - Positive Overall Report").first().json;

const requestedRunId = String(
  webhook.query?.analysis_run_id ?? ""
).trim();

// 指定批次：只查询该批次
// 未指定批次：保持原来查询最新报告的行为
const matchingRows = requestedRunId
  ? rows.filter(row =>
      String(row.analysis_run_id ?? "").trim() === requestedRunId
    )
  : [...rows];

// ============================================================
// 2. 没有找到对应报告
// ============================================================

if (!matchingRows.length) {
  return [
    {
      json: {
        success: true,
        data: null,
        message: "No Positive Overall Report found"
      }
    }
  ];
}

// ============================================================
// 3. 按时间排序，最新报告排在最前面
// ============================================================

matchingRows.sort((a, b) => {

  const getTime = (row) => {

    const raw =
      row.generated_at ||
      row.updatedAt ||
      row.createdAt ||
      "";

    const time = new Date(raw).getTime();

    return Number.isFinite(time)
      ? time
      : 0;
  };

  return getTime(b) - getTime(a);
});

const latest = matchingRows[0];

// ============================================================
// 4. 解析报告 JSON
// ============================================================

let report = {};

try {
  report = JSON.parse(
    latest.report_json || "{}"
  );
} catch (error) {
  throw new Error(
    "Invalid report_json in positive_overall_reports"
  );
}

// ============================================================
// 5. 构建前端需要的返回格式
// ============================================================

return [
  {
    json: {
      success: true,

      data: {

        report_key:
          latest.report_key,

        analysis_run_id:
          latest.analysis_run_id,

        report_version:
          latest.report_version,

        positive_cluster_count:
          Number(latest.positive_cluster_count || 0),

        positive_feedback_count:
          Number(latest.positive_feedback_count || 0),

        overall_summary:
          report.overall_summary ||
          latest.overall_summary ||
          "",

        core_strengths:
          Array.isArray(report.core_strengths)
            ? report.core_strengths
            : [],

        cross_cluster_patterns:
          Array.isArray(report.cross_cluster_patterns)
            ? report.cross_cluster_patterns
            : [],

        product_implication:
          report.product_implication || "",

        representative_signals:
          Array.isArray(report.representative_signals)
            ? report.representative_signals
            : [],

        limitations:
          report.limitations ||
          latest.limitations ||
          "",

        generated_at:
          latest.generated_at || "",

        validation_status:
          latest.validation_status || ""
      }
    }
  }
];

