parameters.jsCode:
const input = $input.first().json;

// Webhook 的 POST JSON 一般在 body 里面
const body = input.body ?? input;


// ============================================================
// 1. Read fields
// ============================================================

const reviewKey =
  String(body.review_key ?? '').trim();

const reviewStatus =
  String(body.review_status ?? '').trim();

const reviewComment =
  String(body.review_comment ?? '').trim();

const reviewedBy =
  String(body.reviewed_by ?? '').trim();


// ============================================================
// 2. Validate
// ============================================================

if (!reviewKey) {
  throw new Error('Missing review_key');
}

const allowedStatuses = [
  'approved',
  'modified',
  'rejected'
];

if (!allowedStatuses.includes(reviewStatus)) {
  throw new Error(
    `Invalid review_status: ${reviewStatus}`
  );
}

if (!reviewedBy) {
  throw new Error('Missing reviewed_by');
}


// 驳回时要求填写原因
if (
  reviewStatus === 'rejected' &&
  !reviewComment
) {
  throw new Error(
    'Rejected review requires review_comment'
  );
}


// ============================================================
// 3. Base review data
// ============================================================

const result = {

  review_key:
    reviewKey,

  review_status:
    reviewStatus,

  review_comment:
    reviewComment,

  reviewed_by:
    reviewedBy,

  reviewed_at:
    new Date().toISOString(),

  is_modified:
    reviewStatus === 'modified'
};


// ============================================================
// 4. PM edited Insight
// 只有 modified 才处理这些字段
// ============================================================

if (reviewStatus === 'modified') {

  result.pm_insight_summary =
    String(
      body.pm_insight_summary ?? ''
    ).trim();

  result.pm_insight_user_need =
    String(
      body.pm_insight_user_need ?? ''
    ).trim();

  result.pm_product_implication =
    String(
      body.pm_product_implication ?? ''
    ).trim();

  result.pm_followup_edited =
    String(
      body.pm_followup_edited ?? ''
    ).trim();
}


// ============================================================
// 5. Output
// ============================================================

return [
  {
    json: result
  }
];

const webhook = $("Webhook - PM Review Data").first().json;
const query = webhook.query ?? {};
const requestedRunId = String(query.analysis_run_id ?? "").trim();

// Always Output Data may provide an empty placeholder object when the table has no rows.
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0 && String(row.analysis_run_id ?? "").trim());

// No analysis_run_id means the front end is asking for the list of batches that still exist
// in pm_review_items. This intentionally excludes stale IDs saved in the browser.
if (!requestedRunId) {
  const availableBatches = [...new Set(
    rows.map(row => String(row.analysis_run_id ?? "").trim()).filter(Boolean)
  )]
    .sort((a, b) => b.localeCompare(a))
    .map(id => ({
      id,
      label: `分析批次 · ${id.replace(/^run_/, "").slice(0, 14)}`
    }));

  return [{
    json: {
      success: true,
      mode: "batch_list",
      total_batches: availableBatches.length,
      available_batches: availableBatches,
      data: []
    }
  }];
}

// Specific batch query: only return rows from the requested analysis_run_id.
const filteredRows = rows.filter(row =>
  String(row.analysis_run_id ?? "").trim() === requestedRunId
);

const batchWriteComplete = filteredRows.some(
  row => row.batch_write_complete === true
);

return [{
  json: {
    success: true,
    analysis_run_id: requestedRunId,
    total: filteredRows.length,
    batch_write_complete: batchWriteComplete,
    data: filteredRows
  }
}];

const items = $input.all();

// 1. 检查是否收到质量筛选结果
if (items.length === 0) {
  throw new Error(
    "QUALITY_FILTER_EMPTY_OUTPUT: No quality filter results received"
  );
}

// 2. 防止异常结果被当成正常无效评论
for (const item of items) {
  const row = item.json;

  if (
    row.parse_status !== "success" ||
    typeof row.is_valid !== "boolean"
  ) {
    throw new Error(
      "QUALITY_FILTER_INVALID_RESULT: Invalid quality filter output"
    );
  }
}

// 3. 统计有效评论
const validCount = items.filter(
  item => item.json.is_valid === true
).length;

// 4. 有有效评论：原样交给后面的 IF 节点
if (validCount > 0) {
  return items;
}

// 5. 全部无效：生成唯一的批次状态标记
const analysisRunId = String(
  $("Trigger - External Analysis")
    .first()
    .json
    .analysis_run_id ?? ""
).trim();

if (!analysisRunId) {
  throw new Error(
    "Missing analysis_run_id for empty valid-review batch"
  );
}

return [
  {
    json: {
      analysis_run_id: analysisRunId,
      is_valid: false,
      no_valid_reviews: true,
      total_review_count: items.length,
      valid_review_count: 0,
      status_message: "本批次没有可分析的有效评论"
    }
  }
];

// 获取刚刚成功入库的所有记录
const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  throw new Error("No inserted PM Review rows");
}

// 获取本次分析批次编号
const analysisRunId = String(
  rows[0].analysis_run_id ?? ""
).trim();

// 确保所有记录来自同一个批次
if (
  !analysisRunId ||
  rows.some(row =>
    String(row.analysis_run_id ?? "").trim()
      !== analysisRunId
  )
) {
  throw new Error("Batch ID mismatch");
}

// 选择最后一条入库记录
const lastRow = rows[rows.length - 1];

const rowId = Number(lastRow.id);

if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("Invalid inserted row ID");
}

// 准备在最后一条记录上写入完成标记
return [{
  json: {
    id: rowId,
    analysis_run_id: analysisRunId,
    batch_write_complete: true,
    inserted_count: rows.length
  }
}];

const OLD_RUN_ID = 'run_20260929015112_293';

const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  throw new Error('No PM Review rows to write');
}

const runId = String(
  rows[0].analysis_run_id ?? ''
).trim();

if (!runId || runId === OLD_RUN_ID) {
  throw new Error(
    'Unsafe analysis_run_id: refusing database write'
  );
}

const seenKeys = new Set();

// 只保留 pm_review_items 表中已有的列
const allowedFields = [
  'review_key',
  'analysis_run_id',
  'final_cluster_id',
  'final_cluster_name',
  'issue_categories',
  'issue_features',
  'feedback_count',
  'priority_level',
  'priority_score',
  'priority_rank',
  'insight_type',
  'insight_summary',
  'insight_user_need',
  'product_implication',
  'pm_followup',
  'representative_comment',
  'pm_insight_summary',
  'pm_insight_user_need',
  'pm_product_implication',
  'pm_followup_edited',
  'review_status',
  'review_comment',
  'reviewed_by',
  'reviewed_at'
];

return rows.map(row => {

  const clusterId = String(
    row.final_cluster_id ?? ''
  ).trim();

  const expectedKey = `${runId}__${clusterId}`;

  if (
    !clusterId ||
    row.analysis_run_id !== runId ||
    row.review_key !== expectedKey
  ) {
    throw new Error(
      `Invalid review key or batch: ${row.review_key}`
    );
  }

  if (seenKeys.has(expectedKey)) {
    throw new Error(
      `Duplicate review_key: ${expectedKey}`
    );
  }

  seenKeys.add(expectedKey);

  if (!['pending', 'not_required'].includes(row.review_status)) {
    throw new Error(
      `Unexpected review_status: ${row.review_status}`
    );
  }

  const cleanRow = {};

  for (const field of allowedFields) {
    if (Object.prototype.hasOwnProperty.call(row, field)) {
      cleanRow[field] = row[field];
    }
  }

  return { json: cleanRow };
});

const items = $input.all();

return items.map(item => {

  const j = item.json;

  // =========================
  // 1. 检查批次编号
  // =========================

  const analysisRunId = String(
    j.analysis_run_id ?? ''
  ).trim();

  const clusterId = String(
    j.final_cluster_id ?? ''
  ).trim();

  if (!analysisRunId || !clusterId) {
    throw new Error(
      'Missing analysis_run_id or final_cluster_id'
    );
  }

  // =========================
  // 2. 生成唯一审核 Key
  // =========================

  const reviewKey =
    `${analysisRunId}__${clusterId}`;

  const insightType =
    j.insight_type ?? 'problem';

  return {
    json: {

      // =========================
      // 唯一审核标识
      // =========================

      review_key:
        reviewKey,

      analysis_run_id:
        analysisRunId,


      // =========================
      // Cluster 基础信息
      // =========================

      final_cluster_id:
        clusterId,

      final_cluster_name:
        j.final_cluster_name ?? '',

      issue_categories:
        Array.isArray(j.issue_categories)
          ? j.issue_categories.join(' / ')
          : (j.issue_categories ?? ''),

      issue_features:
        Array.isArray(j.issue_features)
          ? j.issue_features.join(' / ')
          : (j.issue_features ?? ''),


      // =========================
      // 关键统计
      // =========================

      feedback_count:
        j.feedback_count ?? 0,

      issue_count:
        j.issue_count ?? 0,

      feedback_share_pct:
        j.feedback_share_pct ?? null,

      avg_severity:
        j.avg_severity ?? null,

      max_severity:
        j.max_severity ?? null,

      negative_rate_pct:
        j.negative_rate_pct ?? null,


      // =========================
      // Priority
      // =========================

      priority_level:
        j.priority_level ?? null,

      priority_score:
        j.priority_score ?? null,

      priority_rank:
        j.priority_rank ?? null,


      // =========================
      // Product Insight
      // =========================

      insight_type:
        insightType,

      insight_summary:
        j.insight_summary ?? '',

      user_signal:
        j.user_signal ?? '',

      insight_user_need:
        j.insight_user_need ?? '',

      product_implication:
        j.product_implication ?? '',

      pm_followup:
        j.pm_followup ?? '',

      evidence_summary:
        j.evidence_summary ?? '',

      insight_limitations:
        j.insight_limitations ?? '',


      // =========================
      // 原始评论证据
      // =========================

      representative_comment:
        j.representative_comment ?? '',


      // =========================
      // PM 编辑字段
      // =========================

      pm_insight_summary:
        '',

      pm_insight_user_need:
        '',

      pm_product_implication:
        '',

      pm_followup_edited:
        '',


      // =========================
      // PM Human Review
      // =========================

      review_status:
        insightType === 'positive'
          ? 'not_required'
          : 'pending',

      review_comment:
        '',

      reviewed_by:
        '',

      reviewed_at:
        ''

    }
  };

});

const requestedLimit = Number($("Generate Pages").first().json.limit);


if (
  !Number.isInteger(requestedLimit) ||
  requestedLimit < 10 ||
  requestedLimit > 1000
) {
  throw new Error("Invalid requested limit");
}

const items = $input.all();

const seenIds = new Set();
const results = [];

for (const item of items) {
  const row = item.json;

  const content = String(row.content ?? "").trim();
  const commentId = String(row.source_comment_id ?? "").trim();

  // 跳过空评论
  if (!content) {
    continue;
  }

  // 根据应用宝评论 ID 去重
  if (commentId && seenIds.has(commentId)) {
    continue;
  }

  if (commentId) {
    seenIds.add(commentId);
  }

  results.push({
    json: {
      ...row,
      content
    }
  });

  // 达到要求数量就停止
  if (results.length >= requestedLimit) {
    break;
  }
}

return results;

// ============================================================
// 1. DeepSeek response
// ============================================================

const response = $input.first().json;

const content =
  response?.choices?.[0]?.message?.content;

if (
  !content ||
  typeof content !== 'string'
) {
  throw new Error(
    'Missing DeepSeek choices[0].message.content'
  );
}


// ============================================================
// 2. Get original Positive Overall input
// ============================================================

const source =
  $("Build Positive Overall Input")
    .first()
    .json;


if (!source) {
  throw new Error(
    'Missing Build Positive Overall Input data'
  );
}


// ============================================================
// 3. Parse source Positive Insights
// ============================================================

let positiveInsights;

try {

  positiveInsights =
    JSON.parse(
      source.positive_insights_json
    );

} catch (error) {

  throw new Error(
    'Invalid positive_insights_json'
  );
}


if (
  !Array.isArray(positiveInsights) ||
  positiveInsights.length === 0
) {

  throw new Error(
    'Positive insights source is empty'
  );
}


// ============================================================
// 4. Build validation maps
// ============================================================

const allowedClusterIds =
  new Set(
    positiveInsights.map(
      item =>
        String(
          item.final_cluster_id || ''
        )
    )
  );


const representativeComments =
  new Map();

for (
  const item of positiveInsights
) {

  representativeComments.set(
    String(
      item.final_cluster_id || ''
    ),

    String(
      item.representative_comment || ''
    )
  );
}


// ============================================================
// 5. Clean AI JSON text
// ============================================================

let cleaned =
  content.trim();


// 防止模型偶尔返回 ```json ... ```
cleaned =
  cleaned
    .replace(
      /^```json\s*/i,
      ''
    )
    .replace(
      /^```\s*/i,
      ''
    )
    .replace(
      /\s*```$/,
      ''
    )
    .trim();


// ============================================================
// 6. Parse AI JSON
// ============================================================

let report;

try {

  report =
    JSON.parse(cleaned);

} catch (error) {

  throw new Error(
    'DeepSeek returned invalid JSON: ' +
    error.message
  );
}


// ============================================================
// 7. Helper validators
// ============================================================

function requireString(
  value,
  fieldName
) {

  if (
    typeof value !== 'string' ||
    !value.trim()
  ) {

    throw new Error(
      `Missing or invalid ${fieldName}`
    );
  }

  return value.trim();
}


function requireArray(
  value,
  fieldName
) {

  if (!Array.isArray(value)) {

    throw new Error(
      `${fieldName} must be an array`
    );
  }

  return value;
}


// ============================================================
// 8. Validate top-level fields
// ============================================================

const overallSummary =
  requireString(
    report.overall_summary,
    'overall_summary'
  );


const coreStrengths =
  requireArray(
    report.core_strengths,
    'core_strengths'
  );


// 根据当前批次真实正面 Cluster 数量
// 动态确定核心优势数量上限
const maxCoreStrengths = Math.min(
  5,
  positiveInsights.length
);

if (
  coreStrengths.length < 1 ||
  coreStrengths.length > maxCoreStrengths
) {

  throw new Error(
    `core_strengths must contain 1-${maxCoreStrengths} supported items`
  );
}


const crossClusterPatterns =
  requireArray(
    report.cross_cluster_patterns,
    'cross_cluster_patterns'
  );


const productImplication =
  requireString(
    report.product_implication,
    'product_implication'
  );


const representativeSignals =
  requireArray(
    report.representative_signals,
    'representative_signals'
  );


if (
  representativeSignals.length > 3
) {

  throw new Error(
    'representative_signals must contain at most 3 items'
  );
}


const limitations =
  requireString(
    report.limitations,
    'limitations'
  );


// ============================================================
// 9. Validate core strengths
// ============================================================

for (
  let i = 0;
  i < coreStrengths.length;
  i++
) {

  const strength =
    coreStrengths[i];


  requireString(
    strength.strength_name,
    `core_strengths[${i}].strength_name`
  );


  requireString(
    strength.summary,
    `core_strengths[${i}].summary`
  );


  requireString(
    strength.user_value,
    `core_strengths[${i}].user_value`
  );


  const ids =
    requireArray(
      strength.supporting_cluster_ids,
      `core_strengths[${i}].supporting_cluster_ids`
    );


  if (!ids.length) {

    throw new Error(
      `core_strengths[${i}] has no supporting_cluster_ids`
    );
  }


  for (const id of ids) {

    if (
      !allowedClusterIds.has(
        String(id)
      )
    ) {

      throw new Error(
        `Invalid supporting_cluster_id: ${id}`
      );
    }
  }
}


// ============================================================
// 10. Validate cross-cluster patterns
// ============================================================

for (
  let i = 0;
  i < crossClusterPatterns.length;
  i++
) {

  requireString(
    crossClusterPatterns[i],
    `cross_cluster_patterns[${i}]`
  );
}


// ============================================================
// 11. Validate representative signals
// 必须来自真实 representative_comment
// ============================================================

for (
  let i = 0;
  i < representativeSignals.length;
  i++
) {

  const signal =
    representativeSignals[i];


  const clusterId =
    requireString(
      signal.final_cluster_id,
      `representative_signals[${i}].final_cluster_id`
    );


  const comment =
    requireString(
      signal.comment,
      `representative_signals[${i}].comment`
    );


  if (
    !allowedClusterIds.has(
      clusterId
    )
  ) {

    throw new Error(
      `Invalid representative cluster id: ${clusterId}`
    );
  }


  const originalComment =
    representativeComments.get(
      clusterId
    ) || '';


  if (
    comment !== originalComment
  ) {

    throw new Error(
      `Representative comment mismatch for ${clusterId}`
    );
  }
}


// ============================================================
// 12. Build final validated report
// ============================================================

const validatedReport = {

  overall_summary:
    overallSummary,

  core_strengths:
    coreStrengths,

  cross_cluster_patterns:
    crossClusterPatterns,

  product_implication:
    productImplication,

  representative_signals:
    representativeSignals,

  limitations:
    limitations
};


// ============================================================
// 13. Output for Data Table
// ============================================================

return [
  {
    json: {

      report_key:
        source.report_key,

      analysis_run_id:
        source.analysis_run_id,

      report_version:
        source.report_version,

      positive_cluster_count:
        Number(
          source.positive_cluster_count || 0
        ),

      positive_feedback_count:
        Number(
          source.positive_feedback_count || 0
        ),

      overall_summary:
        overallSummary,

      report_json:
        JSON.stringify(
          validatedReport
        ),

      limitations:
        limitations,

      generated_at:
        new Date().toISOString(),

      validation_status:
        'passed'
    }
  }
];

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0);

// 获取本次真实分析批次
const analysisRunId = String(
  $("Trigger - External Analysis").first().json.analysis_run_id ?? ""
).trim();

if (!analysisRunId) {
  throw new Error("Missing current analysis_run_id");
}

// 没有正向洞察是允许的业务结果，不应将整次分析标记为失败。
const noPositiveInsightsOutput = () => [
  {
    json: {
      no_positive_insights: true,
      analysis_run_id: analysisRunId,
      positive_cluster_count: 0,
      positive_feedback_count: 0,
      status_message: "分析已完成；本批次未发现可汇总的正向反馈，未生成整体正向报告"
    }
  }
];

// 查询结果为空，表示本批次没有可用于整体正向报告的洞察。
if (rows.length === 0) {
  return noPositiveInsightsOutput();
}

// 校验查询结果是否全部属于本次批次，防止跨批次混入。
const wrongBatchRows = rows.filter(row =>
  String(row.analysis_run_id ?? "").trim() !== analysisRunId
);

if (wrongBatchRows.length > 0) {
  throw new Error(
    `Positive insights contain another analysis batch: ${analysisRunId}`
  );
}

