const items = $input.all();

const results = [];


// ============================================================
// Helpers
// ============================================================

const cleanJsonText = (text) => {

  if (typeof text !== 'string') {
    return '';
  }

  return text
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
};


const requiredFields = [
  'final_cluster_id',
  'insight_type',
  'insight_summary',
  'user_signal',
  'user_need',
  'product_implication',
  'pm_followup',
  'evidence_summary',
  'limitations'
];


// ============================================================
// Parse Each Retry Result
// ============================================================

for (const item of items) {

  const j = item.json;


  // ----------------------------------------------------------
  // 1. Read Retry Response
  // ----------------------------------------------------------

  const content =
    j?.choices?.[0]?.message?.content
    ?? j?.data?.choices?.[0]?.message?.content
    ?? j?.body?.choices?.[0]?.message?.content
    ?? '';


  // ----------------------------------------------------------
  // 2. Build clean source object
  // ----------------------------------------------------------
  //
  // 删除 HTTP Response 字段和第一次失败留下的 Insight 字段。
  // Cluster 原始数据全部保留。
  // ----------------------------------------------------------

  const source = { ...j };

  const fieldsToRemove = [
    'choices',
    'data',
    'body',
    'id',
    'object',
    'created',
    'model',
    'usage',
    'system_fingerprint',

    'insight_type',
    'insight_summary',
    'user_signal',
    'insight_user_need',
    'product_implication',
    'pm_followup',
    'evidence_summary',
    'insight_limitations',

    'insight_parse_success',
    'insight_parse_error',
    'insight_raw_output',
    'product_insight_version'
  ];

  for (const field of fieldsToRemove) {
    delete source[field];
  }


  // ----------------------------------------------------------
  // 3. Parse Retry JSON
  // ----------------------------------------------------------

  let parsed = null;
  let parseError = null;

  const cleaned =
    cleanJsonText(content);


  if (!cleaned) {

    parseError =
      'EMPTY_RETRY_RESPONSE';

  } else {

    try {

      parsed =
        JSON.parse(cleaned);

    } catch (error) {

      parseError =
        `JSON_PARSE_ERROR: ${error.message}`;

    }

  }


  // ----------------------------------------------------------
  // 4. Validate JSON Object
  // ----------------------------------------------------------

  if (
    !parseError &&
    (
      !parsed ||
      typeof parsed !== 'object' ||
      Array.isArray(parsed)
    )
  ) {

    parseError =
      'INVALID_JSON_OBJECT';

  }


  // ----------------------------------------------------------
  // 5. Validate Required Fields
  // ----------------------------------------------------------

  if (!parseError) {

    for (const field of requiredFields) {

      if (
        parsed[field] === undefined ||
        parsed[field] === null ||
        String(parsed[field]).trim() === ''
      ) {

        parseError =
          `MISSING_REQUIRED_FIELD: ${field}`;

        break;
      }

    }

  }


  // ----------------------------------------------------------
  // 6. Validate Insight Type
  // ----------------------------------------------------------

  if (
    !parseError &&
    parsed.insight_type !== 'problem'
  ) {

    parseError =
      `INVALID_INSIGHT_TYPE: ${parsed.insight_type}`;

  }


  // ----------------------------------------------------------
  // 7. Validate Cluster ID
  // ----------------------------------------------------------

  if (
    !parseError &&
    source.final_cluster_id &&
    parsed.final_cluster_id !==
      source.final_cluster_id
  ) {

    parseError =
      `CLUSTER_ID_MISMATCH: expected ${source.final_cluster_id}, got ${parsed.final_cluster_id}`;

  }


  // ==========================================================
  // Success
  // ==========================================================

  if (!parseError) {

    results.push({
      json: {

        ...source,

        insight_type:
          'problem',

        insight_summary:
          String(parsed.insight_summary).trim(),

        user_signal:
          String(parsed.user_signal).trim(),

        insight_user_need:
          String(parsed.user_need).trim(),

        product_implication:
          String(parsed.product_implication).trim(),

        pm_followup:
          String(parsed.pm_followup).trim(),

        evidence_summary:
          String(parsed.evidence_summary).trim(),

        insight_limitations:
          String(parsed.limitations).trim(),

        insight_parse_success:
          true,

        insight_parse_error:
          null,

        insight_retry_attempted:
          true,

        insight_retry_success:
          true,

        product_insight_version:
          'problem_v1'
      }
    });

  }


  // ==========================================================
  // Failure Again
  // ==========================================================

  else {

    results.push({
      json: {

        ...source,

        insight_type:
          'problem',

        insight_summary:
          null,

        user_signal:
          null,

        insight_user_need:
          null,

        product_implication:
          null,

        pm_followup:
          null,

        evidence_summary:
          null,

        insight_limitations:
          null,

        insight_parse_success:
          false,

        insight_parse_error:
          parseError,

        insight_raw_output:
          content,

        insight_retry_attempted:
          true,

        insight_retry_success:
          false,

        product_insight_version:
          'problem_v1'
      }
    });

  }

}


return results;

const items = $input.all().map(item => ({
  json: { ...item.json }
}));

const errors = [];

const addError = (code, message, clusterId = null) => {
  errors.push({
    code,
    cluster_id: clusterId,
    message
  });
};


// ============================================================
// 1. Helpers
// ============================================================

const uniqueDefinedNumbers = (values) => {
  return [
    ...new Set(
      values
        .filter(v => v !== null && v !== undefined && v !== '')
        .map(v => Number(v))
        .filter(v => Number.isFinite(v))
    )
  ];
};

const uniqueDefinedStrings = (values) => {
  return [
    ...new Set(
      values
        .filter(v => v !== null && v !== undefined && v !== '')
        .map(v => String(v))
    )
  ];
};


// ============================================================
// 2. Actual Output Counts
// ============================================================

const totalCount = items.length;

const problemItems = items.filter(
  item => item.json.insight_type === 'problem'
);

const positiveItems = items.filter(
  item => item.json.insight_type === 'positive'
);

const problemCount = problemItems.length;
const positiveCount = positiveItems.length;


// ============================================================
// 3. Read Expected Counts Dynamically From Upstream Metadata
// ============================================================
//
// 优先使用 Priority 阶段已经验证过的元数据：
//
// priority_total_cluster_count
// priority_eligible_cluster_count
// priority_excluded_positive_count
//
// 如果不存在，则 fallback 到 total_final_cluster_count。
//
// ============================================================

const totalClusterMetaValues = uniqueDefinedNumbers(
  items.map(item =>
    item.json.priority_total_cluster_count ??
    item.json.total_final_cluster_count
  )
);

const eligibleMetaValues = uniqueDefinedNumbers(
  items.map(item =>
    item.json.priority_eligible_cluster_count
  )
);

const excludedPositiveMetaValues = uniqueDefinedNumbers(
  items.map(item =>
    item.json.priority_excluded_positive_count
  )
);


// ============================================================
// 4. Validate Metadata Consistency
// ============================================================

if (totalClusterMetaValues.length === 0) {

  addError(
    'MISSING_TOTAL_CLUSTER_METADATA',
    'Cannot determine expected total cluster count from upstream metadata'
  );

}

if (totalClusterMetaValues.length > 1) {

  addError(
    'INCONSISTENT_TOTAL_CLUSTER_METADATA',
    `Found inconsistent total cluster counts: ${totalClusterMetaValues.join(', ')}`
  );

}


if (eligibleMetaValues.length === 0) {

  addError(
    'MISSING_ELIGIBLE_CLUSTER_METADATA',
    'Cannot determine expected eligible cluster count from upstream metadata'
  );

}

if (eligibleMetaValues.length > 1) {

  addError(
    'INCONSISTENT_ELIGIBLE_CLUSTER_METADATA',
    `Found inconsistent eligible cluster counts: ${eligibleMetaValues.join(', ')}`
  );

}


if (excludedPositiveMetaValues.length === 0) {

  addError(
    'MISSING_POSITIVE_CLUSTER_METADATA',
    'Cannot determine expected excluded positive cluster count from upstream metadata'
  );

}

if (excludedPositiveMetaValues.length > 1) {

  addError(
    'INCONSISTENT_POSITIVE_CLUSTER_METADATA',
    `Found inconsistent positive cluster counts: ${excludedPositiveMetaValues.join(', ')}`
  );

}


// ============================================================
// 5. Resolve Expected Counts
// ============================================================

const expectedTotalCount =
  totalClusterMetaValues.length === 1
    ? totalClusterMetaValues[0]
    : null;

const expectedProblemCount =
  eligibleMetaValues.length === 1
    ? eligibleMetaValues[0]
    : null;

const expectedPositiveCount =
  excludedPositiveMetaValues.length === 1
    ? excludedPositiveMetaValues[0]
    : null;


// ============================================================
// 6. Validate Counts
// ============================================================

if (
  expectedTotalCount !== null &&
  totalCount !== expectedTotalCount
) {

  addError(
    'TOTAL_COUNT_MISMATCH',
    `Expected ${expectedTotalCount} Product Insights, got ${totalCount}`
  );

}


if (
  expectedProblemCount !== null &&
  problemCount !== expectedProblemCount
) {

  addError(
    'PROBLEM_COUNT_MISMATCH',
    `Expected ${expectedProblemCount} problem insights, got ${problemCount}`
  );

}


if (
  expectedPositiveCount !== null &&
  positiveCount !== expectedPositiveCount
) {

  addError(
    'POSITIVE_COUNT_MISMATCH',
    `Expected ${expectedPositiveCount} positive insights, got ${positiveCount}`
  );

}


// ============================================================
// 7. Validate Count Relationship
// ============================================================

if (
  expectedProblemCount !== null &&
  expectedPositiveCount !== null &&
  expectedTotalCount !== null &&
  expectedProblemCount + expectedPositiveCount !== expectedTotalCount
) {

  addError(
    'UPSTREAM_COUNT_RELATION_MISMATCH',
    `Expected problem + positive to equal total, but ${expectedProblemCount} + ${expectedPositiveCount} != ${expectedTotalCount}`
  );

}


if (problemCount + positiveCount !== totalCount) {

  addError(
    'OUTPUT_TYPE_COUNT_MISMATCH',
    `Problem + positive count does not equal output total: ${problemCount} + ${positiveCount} != ${totalCount}`
  );

}


// ============================================================
// 8. Unique Cluster IDs
// ============================================================

const clusterIds = items.map(
  item => item.json.final_cluster_id
);

const missingClusterIds = clusterIds.filter(
  id => id === null || id === undefined || String(id).trim() === ''
);

if (missingClusterIds.length > 0) {

  addError(
    'MISSING_CLUSTER_ID',
    `${missingClusterIds.length} items have no final_cluster_id`
  );

}


const validClusterIds = clusterIds
  .filter(id =>
    id !== null &&
    id !== undefined &&
    String(id).trim() !== ''
  )
  .map(id => String(id));


const uniqueClusterIds =
  new Set(validClusterIds);

if (uniqueClusterIds.size !== validClusterIds.length) {

  addError(
    'DUPLICATE_CLUSTER_ID',
    `Expected unique final_cluster_id values, got ${validClusterIds.length} rows but only ${uniqueClusterIds.size} unique IDs`
  );

}


// ============================================================
// 9. Required Insight Fields
// ============================================================

const requiredInsightFields = [
  'final_cluster_id',
  'insight_type',
  'insight_summary',
  'user_signal',
  'insight_user_need',
  'product_implication',
  'pm_followup',
  'evidence_summary',
  'insight_limitations'
];


// ============================================================
// 10. Validate Every Item
// ============================================================

for (const item of items) {

  const j = item.json;

  const clusterId =
    j.final_cluster_id || 'unknown_cluster';


  // ----------------------------------------------------------
  // Upstream validation
  // ----------------------------------------------------------

  if (
    j.priority_validation_status &&
    j.priority_validation_status !== 'success'
  ) {

    addError(
      'UPSTREAM_PRIORITY_VALIDATION_FAILED',
      `priority_validation_status=${j.priority_validation_status}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Parse Success
  // ----------------------------------------------------------

  if (j.insight_parse_success !== true) {

    addError(
      'INSIGHT_PARSE_FAILED',
      j.insight_parse_error
        ? `Insight parse failed: ${j.insight_parse_error}`
        : 'insight_parse_success is not true',
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Required Fields
  // ----------------------------------------------------------

  for (const field of requiredInsightFields) {

    if (
      j[field] === undefined ||
      j[field] === null ||
      String(j[field]).trim() === ''
    ) {

      addError(
        'MISSING_INSIGHT_FIELD',
        `${field} is missing`,
        clusterId
      );

    }

  }


  // ----------------------------------------------------------
  // Problem Rules
  // ----------------------------------------------------------

  if (j.insight_type === 'problem') {

    if (j.priority_eligible !== true) {

      addError(
        'PROBLEM_ELIGIBILITY_MISMATCH',
        'Problem insight must have priority_eligible=true',
        clusterId
      );

    }


    if (
      j.priority_score === null ||
      j.priority_score === undefined
    ) {

      addError(
        'PROBLEM_PRIORITY_SCORE_MISSING',
        'Problem insight must have priority_score',
        clusterId
      );

    }


    if (
      j.priority_rank === null ||
      j.priority_rank === undefined
    ) {

      addError(
        'PROBLEM_PRIORITY_RANK_MISSING',
        'Problem insight must have priority_rank',
        clusterId
      );

    }


    if (
      !['high', 'medium', 'low'].includes(
        j.priority_level
      )
    ) {

      addError(
        'INVALID_PROBLEM_PRIORITY_LEVEL',
        `Problem insight has invalid priority_level=${j.priority_level}`,
        clusterId
      );

    }


    if (
      j.product_insight_version !== 'problem_v1'
    ) {

      addError(
        'INVALID_PROBLEM_INSIGHT_VERSION',
        `Expected product_insight_version=problem_v1, got ${j.product_insight_version}`,
        clusterId
      );

    }

  }


  // ----------------------------------------------------------
  // Positive Rules
  // ----------------------------------------------------------

  else if (j.insight_type === 'positive') {

    if (j.priority_eligible !== false) {

      addError(
        'POSITIVE_ELIGIBILITY_MISMATCH',
        'Positive insight must have priority_eligible=false',
        clusterId
      );

    }


    if (j.priority_score !== null) {

      addError(
        'POSITIVE_PRIORITY_SCORE_NOT_NULL',
        'Positive insight must have priority_score=null',
        clusterId
      );

    }


    if (j.priority_rank !== null) {

      addError(
        'POSITIVE_PRIORITY_RANK_NOT_NULL',
        'Positive insight must have priority_rank=null',
        clusterId
      );

    }


    if (j.priority_level !== 'excluded') {

      addError(
        'INVALID_POSITIVE_PRIORITY_LEVEL',
        `Positive insight must have priority_level=excluded, got ${j.priority_level}`,
        clusterId
      );

    }


    if (
      j.product_insight_version !== 'positive_v1'
    ) {

      addError(
        'INVALID_POSITIVE_INSIGHT_VERSION',
        `Expected product_insight_version=positive_v1, got ${j.product_insight_version}`,
        clusterId
      );

    }

  }


  // ----------------------------------------------------------
  // Unknown Type
  // ----------------------------------------------------------

  else {

    addError(
      'INVALID_INSIGHT_TYPE',
      `Unknown insight_type=${j.insight_type}`,
      clusterId
    );

  }

}


// ============================================================
// 11. Validate Problem Priority Ranks
// ============================================================

const problemRanks = problemItems
  .map(item => Number(item.json.priority_rank))
  .filter(rank => Number.isFinite(rank))
  .sort((a, b) => a - b);


if (problemRanks.length !== problemCount) {

  addError(
    'INVALID_PROBLEM_RANK_COUNT',
    `Expected ${problemCount} valid priority ranks, got ${problemRanks.length}`
  );

}


// 连续 rank 应该是 1...N
for (let i = 0; i < problemRanks.length; i++) {

  const expectedRank = i + 1;

  if (problemRanks[i] !== expectedRank) {

    addError(
      'NON_CONTIGUOUS_PRIORITY_RANK',
      `Expected rank ${expectedRank}, got ${problemRanks[i]}`
    );

    break;
  }

}


// ============================================================
// 12. Sort Final Output
// ============================================================
//
// Problem:
// priority_rank ASC
//
// Positive:
// feedback_count DESC
// final_cluster_id ASC
//
// ============================================================

items.sort((a, b) => {

  const A = a.json;
  const B = b.json;


  if (A.insight_type !== B.insight_type) {

    return A.insight_type === 'problem'
      ? -1
      : 1;

  }


  if (A.insight_type === 'problem') {

    return (
      Number(A.priority_rank) -
      Number(B.priority_rank)
    );

  }


  const feedbackDiff =
    Number(B.feedback_count || 0) -
