const normalizeArray = (value) => {

  if (Array.isArray(value)) {
    return [
      ...new Set(
        value
          .map(v => String(v).trim())
          .filter(Boolean)
      )
    ];
  }

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return [];
  }

  return [String(value).trim()];
};


const toDisplayText = (values) => {

  if (!values.length) {
    return '未分类';
  }

  return values.join(' / ');
};


// ============================================================
// Prepare User-facing Priority Issue Fields
// ============================================================

return items.map(item => {

