    json
  };

});

const items = $input.all().map(item => ({
  json: { ...item.json }
}));


// ============================================================
// Helpers
// ============================================================

const clamp = (value, min, max) =>
  Math.min(max, Math.max(min, value));

const round2 = (value) =>
  Math.round((value + Number.EPSILON) * 100) / 100;

const nearlyEqual = (a, b, tolerance = 0.011) =>
  Math.abs(Number(a) - Number(b)) <= tolerance;

const isPurePositive = (json) => {
  const categories = Array.isArray(json.source_categories)
    ? json.source_categories
    : [];

  return (
    categories.length > 0 &&
    categories.every(category => category === '正向体验')
  );
};


// ============================================================
// 1. Basic Counts
// ============================================================

const totalCount = items.length;

const eligibleItems = items.filter(
  item => item.json.priority_eligible === true
);

const excludedItems = items.filter(
  item => item.json.priority_eligible === false
);

const eligibleCount = eligibleItems.length;
const excludedCount = excludedItems.length;

const maxFeedbackCount = Math.max(
  1,
  ...eligibleItems.map(
    item => Number(item.json.feedback_count) || 0
  )
);


// ============================================================
// 2. Collect Validation Errors
// ============================================================

const errors = [];

const addError = (
  code,
  message,
  clusterId = null
) => {

  errors.push({
    code,
    cluster_id: clusterId,
    message
  });

};


// ============================================================
// 3. Global Count Validation
// ============================================================

if (eligibleCount + excludedCount !== totalCount) {

  addError(
    'COUNT_MISMATCH',
    `eligible (${eligibleCount}) + excluded (${excludedCount}) != total (${totalCount})`
  );

}


// ============================================================
// 4. Validate Every Cluster
// ============================================================

for (const item of items) {

  const json = item.json;

  const clusterId =
    json.final_cluster_id || 'unknown_cluster';

  const expectedEligible =
    !isPurePositive(json);


  // ----------------------------------------------------------
  // Formula Version
  // ----------------------------------------------------------

  if (json.priority_formula_version !== 'v1') {

    addError(
      'INVALID_FORMULA_VERSION',
      `Expected priority_formula_version=v1, got ${json.priority_formula_version}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Eligibility
  // ----------------------------------------------------------

  if (json.priority_eligible !== expectedEligible) {

    addError(
      'ELIGIBILITY_MISMATCH',
      `priority_eligible should be ${expectedEligible}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Global Metadata
  // ----------------------------------------------------------

  if (
    Number(json.priority_total_cluster_count) !==
    totalCount
  ) {

    addError(
      'TOTAL_COUNT_METADATA_MISMATCH',
      `priority_total_cluster_count should be ${totalCount}`,
      clusterId
    );

  }


  if (
    Number(json.priority_eligible_cluster_count) !==
    eligibleCount
  ) {

    addError(
      'ELIGIBLE_COUNT_METADATA_MISMATCH',
      `priority_eligible_cluster_count should be ${eligibleCount}`,
      clusterId
    );

  }


  if (
    Number(json.priority_excluded_positive_count) !==
    excludedCount
  ) {

    addError(
      'EXCLUDED_COUNT_METADATA_MISMATCH',
      `priority_excluded_positive_count should be ${excludedCount}`,
      clusterId
    );

  }


  if (
    Number(json.priority_max_feedback_count) !==
    maxFeedbackCount
  ) {

    addError(
      'MAX_FEEDBACK_METADATA_MISMATCH',
      `priority_max_feedback_count should be ${maxFeedbackCount}`,
      clusterId
    );

  }


  // ==========================================================
  // 5. Pure Positive / Excluded Validation
  // ==========================================================

  if (!expectedEligible) {

    if (
      json.priority_exclusion_reason !==
      'pure_positive_cluster'
    ) {

      addError(
        'INVALID_EXCLUSION_REASON',
        'Pure positive cluster must use priority_exclusion_reason=pure_positive_cluster',
        clusterId
      );

    }


    if (json.priority_level !== 'excluded') {

      addError(
        'INVALID_EXCLUDED_LEVEL',
        'Pure positive cluster must have priority_level=excluded',
        clusterId
      );

    }


    const fieldsThatMustBeNull = [
      'frequency_score',
      'severity_score',
      'sentiment_score',
      'priority_score',
      'priority_rank'
    ];

    for (const field of fieldsThatMustBeNull) {

      if (json[field] !== null) {

        addError(
          'EXCLUDED_FIELD_NOT_NULL',
          `${field} must be null for excluded cluster`,
          clusterId
        );

      }

    }

    continue;

  }


  // ==========================================================
  // 6. Eligible Cluster Validation
  // ==========================================================

  if (json.priority_exclusion_reason !== null) {

    addError(
      'UNEXPECTED_EXCLUSION_REASON',
      'Eligible cluster must have priority_exclusion_reason=null',
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Raw Values
  // ----------------------------------------------------------

  const feedbackCount = Math.max(
    0,
    Number(json.feedback_count) || 0
  );

  const avgSeverity = clamp(
    Number(json.avg_severity) || 1,
    1,
    5
  );

  const negativeRate = clamp(
    Number(json.negative_rate) || 0,
    0,
    1
  );

  const neutralRate = clamp(
    Number(json.neutral_rate) || 0,
    0,
    1
  );


  // ----------------------------------------------------------
  // Expected Frequency Score
  // ----------------------------------------------------------

  const expectedFrequencyScore = round2(
    clamp(
      (
        feedbackCount /
        maxFeedbackCount
      ) * 100,
      0,
      100
    )
  );


  if (
    !nearlyEqual(
      json.frequency_score,
      expectedFrequencyScore
    )
  ) {

    addError(
      'FREQUENCY_SCORE_MISMATCH',
      `Expected ${expectedFrequencyScore}, got ${json.frequency_score}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Expected Severity Score
  // ----------------------------------------------------------

  const expectedSeverityScore = round2(
    clamp(
      (
        (avgSeverity - 1) /
        4
      ) * 100,
      0,
      100
    )
  );


  if (
    !nearlyEqual(
      json.severity_score,
      expectedSeverityScore
    )
  ) {

    addError(
      'SEVERITY_SCORE_MISMATCH',
      `Expected ${expectedSeverityScore}, got ${json.severity_score}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Expected Sentiment Score
  // ----------------------------------------------------------

  const expectedSentimentScore = round2(
    clamp(
      (
        negativeRate +
        neutralRate * 0.5
      ) * 100,
      0,
      100
    )
  );


  if (
    !nearlyEqual(
      json.sentiment_score,
      expectedSentimentScore
    )
  ) {

    addError(
      'SENTIMENT_SCORE_MISMATCH',
      `Expected ${expectedSentimentScore}, got ${json.sentiment_score}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Expected Priority Score
  // ----------------------------------------------------------

  const expectedPriorityScore = round2(
    expectedFrequencyScore * 0.40 +
    expectedSeverityScore * 0.40 +
    expectedSentimentScore * 0.20
  );


  if (
    !nearlyEqual(
      json.priority_score,
      expectedPriorityScore
    )
  ) {

    addError(
      'PRIORITY_SCORE_MISMATCH',
      `Expected ${expectedPriorityScore}, got ${json.priority_score}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Score Bounds
  // ----------------------------------------------------------

  const scoreFields = [
    'frequency_score',
    'severity_score',
    'sentiment_score',
    'priority_score'
  ];

  for (const field of scoreFields) {

    const value = Number(json[field]);

    if (
      !Number.isFinite(value) ||
      value < 0 ||
      value > 100
    ) {

      addError(
        'SCORE_OUT_OF_RANGE',
        `${field}=${json[field]} is outside 0-100`,
        clusterId
      );

    }

  }


  // ----------------------------------------------------------
  // Priority Level
  // ----------------------------------------------------------

  let expectedLevel;

  if (expectedPriorityScore >= 65) {

    expectedLevel = 'high';

  } else if (expectedPriorityScore >= 45) {

    expectedLevel = 'medium';

  } else {

    expectedLevel = 'low';

  }


  if (json.priority_level !== expectedLevel) {

    addError(
      'PRIORITY_LEVEL_MISMATCH',
      `Expected ${expectedLevel}, got ${json.priority_level}`,
      clusterId
    );

  }


  // ----------------------------------------------------------
  // Rank Basic Validation
  // ----------------------------------------------------------

  const rank = Number(json.priority_rank);

  if (
    !Number.isInteger(rank) ||
    rank < 1 ||
    rank > eligibleCount
  ) {

    addError(
      'INVALID_PRIORITY_RANK',
      `priority_rank=${json.priority_rank} is invalid`,
      clusterId
    );

  }

}


// ============================================================
// 7. Validate Rank Sequence
// ============================================================

const ranks = eligibleItems
  .map(item => Number(item.json.priority_rank))
  .sort((a, b) => a - b);

const expectedRanks = Array.from(
  { length: eligibleCount },
  (_, index) => index + 1
);


if (
  JSON.stringify(ranks) !==
  JSON.stringify(expectedRanks)
) {

  addError(
    'RANK_SEQUENCE_INVALID',
    `Priority ranks must be continuous from 1 to ${eligibleCount}`
  );

}


// ============================================================
// 8. Validate Current Output Sort Order
// ============================================================

const comparator = (a, b) => {

  const A = a.json;
  const B = b.json;


  // Eligible first
  if (
    A.priority_eligible !==
    B.priority_eligible
  ) {

    return A.priority_eligible ? -1 : 1;

  }


  // Excluded cluster stable ordering
  if (
    !A.priority_eligible &&
    !B.priority_eligible
  ) {

    return String(A.final_cluster_id)
      .localeCompare(
        String(B.final_cluster_id)
      );

  }


  // Priority Score
  if (
    Number(B.priority_score) !==
    Number(A.priority_score)
  ) {

    return (
      Number(B.priority_score) -
      Number(A.priority_score)
    );

  }


  // Feedback Count
  if (
    Number(B.feedback_count) !==
    Number(A.feedback_count)
  ) {

    return (
      Number(B.feedback_count) -
      Number(A.feedback_count)
    );

  }


  // Avg Severity
  if (
    Number(B.avg_severity) !==
    Number(A.avg_severity)
  ) {

    return (
      Number(B.avg_severity) -
      Number(A.avg_severity)
    );

  }


  // Negative Rate
  if (
    Number(B.negative_rate) !==
    Number(A.negative_rate)
  ) {

    return (
      Number(B.negative_rate) -
      Number(A.negative_rate)
    );

  }


  return String(A.final_cluster_id)
    .localeCompare(
      String(B.final_cluster_id)
    );

};


const expectedOrder = [...items]
  .sort(comparator)
  .map(
    item => item.json.final_cluster_id
  );

const actualOrder = items.map(
  item => item.json.final_cluster_id
);


if (
  JSON.stringify(expectedOrder) !==
  JSON.stringify(actualOrder)
) {

  addError(
    'OUTPUT_SORT_ORDER_INVALID',
    'Current item order does not match Priority sorting rules'
  );

}


// ============================================================
// 9. Priority Level Counts
// ============================================================

const levelCounts = {
  high: 0,
  medium: 0,
  low: 0,
  excluded: 0
};


for (const item of items) {

  const level =
    item.json.priority_level;

  if (
    Object.prototype.hasOwnProperty.call(
      levelCounts,
      level
    )
  ) {

    levelCounts[level] += 1;

  }

}


// ============================================================
// 10. Final Validation Status
// ============================================================

const validationStatus =
  errors.length === 0
    ? 'success'
    : 'failed';


// ============================================================
// 11. Append Validation Metadata
// ============================================================

for (const item of items) {

  item.json.priority_validation_version =
    'v1';

  item.json.priority_validation_status =
    validationStatus;

  item.json.priority_validation_checked_count =
    totalCount;

  item.json.priority_validation_error_count =
    errors.length;

  item.json.priority_validation_errors =
    errors;

  item.json.priority_level_counts = {
    ...levelCounts
  };

}


// ============================================================
// 12. Return Original 53 Items
// ============================================================

return items;

