}));

// ---------- Helpers ----------
const clamp = (value, min, max) =>
  Math.min(max, Math.max(min, value));

const round2 = (value) =>
  Math.round((value + Number.EPSILON) * 100) / 100;

// 纯正向 Cluster 不进入 Priority
const isPurePositive = (json) => {
  const categories = Array.isArray(json.source_categories)
    ? json.source_categories
    : [];

  return (
    categories.length > 0 &&
    categories.every(category => category === '正向体验')
  );
};


// ---------- 1. 找出参与 Priority 的 Cluster ----------
const eligibleItems = items.filter(
  item => !isPurePositive(item.json)
);

const excludedPositiveCount =
  items.length - eligibleItems.length;


// ---------- 2. Frequency 标准化基准 ----------
const maxFeedbackCount = Math.max(
  1,
  ...eligibleItems.map(
    item => Number(item.json.feedback_count) || 0
  )
);


// ---------- 3. 计算 Priority ----------
for (const item of items) {

  const json = item.json;

  const excluded = isPurePositive(json);

  // ---------- Global Metadata ----------
  json.priority_formula_version = 'v1';

  json.priority_eligible = !excluded;

  json.priority_total_cluster_count =
    items.length;

  json.priority_eligible_cluster_count =
    eligibleItems.length;

  json.priority_excluded_positive_count =
    excludedPositiveCount;

  json.priority_max_feedback_count =
    maxFeedbackCount;


  // ---------- Pure Positive Cluster ----------
  if (excluded) {

    json.priority_exclusion_reason =
      'pure_positive_cluster';

    json.frequency_score = null;
    json.severity_score = null;
    json.sentiment_score = null;

    json.priority_score = null;
    json.priority_level = 'excluded';
    json.priority_rank = null;

    continue;
  }


  // ---------- Raw Values ----------
  const feedbackCount = Math.max(
    0,
    Number(json.feedback_count) || 0
  );

  const avgSeverity = clamp(
    Number(json.avg_severity) || 1,
    1,
    5
  );

  const negativeRate = clamp(
    Number(json.negative_rate) || 0,
    0,
    1
  );

  const neutralRate = clamp(
    Number(json.neutral_rate) || 0,
    0,
    1
  );


  // ---------- Frequency Score ----------
  // 权重意义：
  // 有多少条不同 Feedback 提到了这个 Cluster
  const frequencyScore = clamp(
    (feedbackCount / maxFeedbackCount) * 100,
    0,
    100
  );


  // ---------- Severity Score ----------
  // avg_severity:
  // 1 -> 0
  // 2 -> 25
  // 3 -> 50
  // 4 -> 75
  // 5 -> 100
  const severityScore = clamp(
    ((avgSeverity - 1) / 4) * 100,
    0,
    100
  );


  // ---------- Sentiment Score ----------
  // Negative = 100% 权重
  // Neutral  = 50% 权重
  // Positive = 0
  const sentimentScore = clamp(
    (
      negativeRate +
      neutralRate * 0.5
    ) * 100,
    0,
    100
  );


  // ---------- Final Priority Score ----------
  // Frequency 40%
  // Severity  40%
  // Sentiment 20%
  const priorityScore =
    frequencyScore * 0.40 +
    severityScore * 0.40 +
    sentimentScore * 0.20;


  json.priority_exclusion_reason = null;

  json.frequency_score =
    round2(frequencyScore);

  json.severity_score =
    round2(severityScore);

  json.sentiment_score =
    round2(sentimentScore);

  json.priority_score =
    round2(priorityScore);


  // ---------- Priority Level ----------
  if (json.priority_score >= 65) {

    json.priority_level = 'high';

  } else if (json.priority_score >= 45) {

    json.priority_level = 'medium';

  } else {

    json.priority_level = 'low';

  }


  // Rank 后面统一计算
  json.priority_rank = null;
}


// ---------- 4. Priority 排序 ----------
items.sort((a, b) => {

  const A = a.json;
  const B = b.json;


  // Eligible 永远放前面
  if (A.priority_eligible !== B.priority_eligible) {

    return A.priority_eligible ? -1 : 1;

  }


  // 两个都是纯正向 Cluster
  if (
    !A.priority_eligible &&
    !B.priority_eligible
  ) {

    return String(A.final_cluster_id)
      .localeCompare(
        String(B.final_cluster_id)
      );

  }


  // ---------- Tie Breaker 1 ----------
  // Priority Score 高的排前面
  if (
    B.priority_score !== A.priority_score
  ) {

    return (
      B.priority_score -
      A.priority_score
    );

  }


  // ---------- Tie Breaker 2 ----------
  // Feedback Count 高的排前面
  if (
    B.feedback_count !== A.feedback_count
  ) {

    return (
      Number(B.feedback_count || 0) -
      Number(A.feedback_count || 0)
    );

  }


  // ---------- Tie Breaker 3 ----------
  // Avg Severity 高的排前面
  if (
    B.avg_severity !== A.avg_severity
  ) {

    return (
      Number(B.avg_severity || 0) -
      Number(A.avg_severity || 0)
    );

  }


  // ---------- Tie Breaker 4 ----------
  // Negative Rate 高的排前面
  if (
    B.negative_rate !== A.negative_rate
  ) {

    return (
      Number(B.negative_rate || 0) -
      Number(A.negative_rate || 0)
    );

  }


  // ---------- Tie Breaker 5 ----------
  // 最终保证排序稳定
  return String(A.final_cluster_id)
    .localeCompare(
      String(B.final_cluster_id)
    );
});


// ---------- 5. Assign Priority Rank ----------
let rank = 0;

for (const item of items) {

  if (item.json.priority_eligible) {

    rank += 1;

    item.json.priority_rank = rank;

  }

}


// ---------- 6. Return ----------
return items;

// ============================================================
// Parse Global Consolidation
//
// 输入：DeepSeek - Global Cluster Consolidation V1
//
// 辅助数据：
// Parse Clustering Result
//
// 功能：
// 1. 解析 final_clusters
// 2. 验证所有第一阶段 Cluster 是否全部且只出现一次
// 3. 将 source_cluster_ids 展开回 member_issue_keys
// 4. 输出最终 Final Cluster
// ============================================================


// ------------------------------------------------------------
// 1. 获取 DeepSeek 输出
// ------------------------------------------------------------

const aiItems = $input.all();

if (aiItems.length !== 1) {
  throw new Error(
    `Global Consolidation 理论上应该只有 1 个 AI 输出，实际=${aiItems.length}`
  );
}

const ai = aiItems[0].json ?? {};


// ------------------------------------------------------------
// 2. 获取第一阶段 Cluster
// ------------------------------------------------------------

const sourceItems =
  $items("Parse Clustering Result", 0);

if (sourceItems.length === 0) {
  throw new Error(
    "没有读取到 Parse Clustering Result 的第一阶段 Cluster"
  );
}


// ------------------------------------------------------------
// 3. 建立 cluster_id → 第一阶段 Cluster 映射
// ------------------------------------------------------------

const sourceClusterMap = new Map();

for (const item of sourceItems) {

  const cluster = item.json ?? {};

  if (cluster.parse_status !== "success") {
    throw new Error(
      `发现第一阶段失败 Cluster：${cluster.group_id ?? "unknown"}`
    );
  }

  const clusterId =
    String(cluster.cluster_id ?? "").trim();

  if (!clusterId) {
    throw new Error(
      "发现第一阶段 cluster_id 为空"
    );
  }

  if (sourceClusterMap.has(clusterId)) {
    throw new Error(
      `发现重复第一阶段 cluster_id：${clusterId}`
    );
  }

  sourceClusterMap.set(
    clusterId,
    cluster
  );
}


// ------------------------------------------------------------
// 4. 提取 DeepSeek Content
// ------------------------------------------------------------

let rawContent =
  ai?.choices?.[0]?.message?.content ?? "";

rawContent =
  String(rawContent)
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

const finishReason =
  ai?.choices?.[0]?.finish_reason ?? null;


// ------------------------------------------------------------
// 5. JSON Parse
// ------------------------------------------------------------

let parsed;

try {

  parsed =
    JSON.parse(rawContent);

} catch (error) {

  throw new Error(
    `Global Consolidation JSON解析失败：${error.message}`
  );
}


// ------------------------------------------------------------
// 6. final_clusters 基础检查
// ------------------------------------------------------------

if (
  !Array.isArray(parsed.final_clusters) ||
  parsed.final_clusters.length === 0
) {

  throw new Error(
    "final_clusters 不存在、不是数组或为空"
  );
}


// ------------------------------------------------------------
// 7. 收集所有 source_cluster_ids
// ------------------------------------------------------------

const allOutputSourceClusterIds = [];

for (const finalCluster of parsed.final_clusters) {

  const ids =
    Array.isArray(finalCluster.source_cluster_ids)
      ? finalCluster.source_cluster_ids
      : [];

  allOutputSourceClusterIds.push(
    ...ids
  );
}


// ------------------------------------------------------------
// 8. 全局完整性检查
// ------------------------------------------------------------

const sourceClusterIds =
  Array.from(sourceClusterMap.keys());

const sourceSet =
  new Set(sourceClusterIds);

const outputSet =
  new Set(allOutputSourceClusterIds);


// Missing
const missingClusterIds =
  sourceClusterIds.filter(
    id => !outputSet.has(id)
  );


// Extra
const extraClusterIds =
  allOutputSourceClusterIds.filter(
    id => !sourceSet.has(id)
  );


// Duplicate
const idCounts = {};

for (const id of allOutputSourceClusterIds) {

  idCounts[id] =
    (idCounts[id] ?? 0) + 1;
}

const duplicateClusterIds =
  Object.entries(idCounts)
    .filter(
      ([_, count]) => count > 1
    )
    .map(
      ([id]) => id
    );


if (
  missingClusterIds.length > 0 ||
  extraClusterIds.length > 0 ||
  duplicateClusterIds.length > 0
) {

  throw new Error(
    [
      "Global Consolidation 完整性检查失败",
      `missing=${missingClusterIds.length}`,
      `extra=${extraClusterIds.length}`,
      `duplicate=${duplicateClusterIds.length}`
    ].join(" | ")
  );
}


// ------------------------------------------------------------
// 9. Final Cluster ID 检查
// ------------------------------------------------------------

const seenFinalClusterIds =
  new Set();


// ------------------------------------------------------------
// 10. 展开 Final Cluster
// ------------------------------------------------------------

const results = [];


for (
  let i = 0;
  i < parsed.final_clusters.length;
  i++
) {

  const finalCluster =
    parsed.final_clusters[i] ?? {};


  // ----------------------------------------------------------
  // Final Cluster ID
  // ----------------------------------------------------------

  const finalClusterId =
    String(
      finalCluster.final_cluster_id ?? ""
    ).trim();


  if (!finalClusterId) {
    throw new Error(
      `第 ${i + 1} 个 Final Cluster 缺少 final_cluster_id`
    );
  }


  if (seenFinalClusterIds.has(finalClusterId)) {
    throw new Error(
      `发现重复 final_cluster_id：${finalClusterId}`
    );
  }

  seenFinalClusterIds.add(
    finalClusterId
  );


  // ----------------------------------------------------------
  // Final Cluster Name
  // ----------------------------------------------------------

  const finalClusterName =
    String(
      finalCluster.final_cluster_name ?? ""
    ).trim();


  if (!finalClusterName) {
    throw new Error(
      `${finalClusterId} 缺少 final_cluster_name`
    );
  }


  // ----------------------------------------------------------
  // Source Cluster IDs
  // ----------------------------------------------------------

  const sourceIds =
    Array.isArray(
      finalCluster.source_cluster_ids
    )
      ? finalCluster.source_cluster_ids
      : [];


  if (sourceIds.length === 0) {
    throw new Error(
      `${finalClusterId} 没有 source_cluster_ids`
    );
  }


  // ----------------------------------------------------------
  // 找回第一阶段 Cluster
  // ----------------------------------------------------------

  const sourceClusters = [];

  for (const sourceId of sourceIds) {

    const sourceCluster =
      sourceClusterMap.get(sourceId);

    if (!sourceCluster) {
      throw new Error(
        `${finalClusterId} 找不到 source cluster：${sourceId}`
      );
    }

    sourceClusters.push(
      sourceCluster
    );
  }


  // ----------------------------------------------------------
  // 合并所有 member_issue_keys
  // ----------------------------------------------------------

  const memberIssueKeys = [];

  for (const sourceCluster of sourceClusters) {

    const members =
      Array.isArray(
        sourceCluster.member_issue_keys
      )
        ? sourceCluster.member_issue_keys
        : [];

    memberIssueKeys.push(
      ...members
    );
  }


  // ----------------------------------------------------------
  // Final Cluster 内部 Issue 重复检查
  // ----------------------------------------------------------

  const memberSet =
    new Set(memberIssueKeys);


  if (
    memberSet.size !==
    memberIssueKeys.length
  ) {

    throw new Error(
      `${finalClusterId} 内存在重复 member_issue_key`
    );
  }


  // ----------------------------------------------------------
  // 收集原始 Category / Feature
  //
  // Consolidation 后可能跨 Category / Feature，
  // 所以使用数组保留来源，而不是强行选一个。
  // ----------------------------------------------------------

  const sourceCategories =
    [
      ...new Set(
        sourceClusters
          .map(c => c.category)
          .filter(Boolean)
      )
    ];


  const sourceFeatures =
    [
      ...new Set(
        sourceClusters
          .map(c => c.feature)
          .filter(Boolean)
      )
    ];


  const sourceClusterNames =
    sourceClusters.map(
      c => c.cluster_name
    );


  // ----------------------------------------------------------
  // 输出 Final Cluster
  // ----------------------------------------------------------

  results.push({

    json: {

      final_cluster_id:
        finalClusterId,

      final_cluster_name:
        finalClusterName,


      source_cluster_ids:
        sourceIds,

      source_cluster_count:
        sourceIds.length,


      source_cluster_names:
        sourceClusterNames,

      source_categories:
        sourceCategories,

      source_features:
        sourceFeatures,


      member_issue_keys:
        memberIssueKeys,

      member_count:
        memberIssueKeys.length,


      consolidation_method:
        sourceIds.length > 1
          ? "global_llm_consolidation"
          : "global_llm_passthrough",

      consolidation_prompt_version:
        "v1",

      consolidation_model:
        ai.model ?? null,

      finish_reason:
        finishReason,


      parse_status:
        "success",

      parse_error:
        null

    }

  });

}


// ------------------------------------------------------------
// 11. Final Cluster 全局 Issue 完整性检查
//
// 第一阶段 Cluster 已经验证覆盖 118 Issue。
// Global Consolidation 不允许丢掉任何 Issue。
// ------------------------------------------------------------

const allFinalIssueKeys =
  results.flatMap(
    item =>
      item.json.member_issue_keys
  );


const issueCounts = {};

for (const key of allFinalIssueKeys) {

  issueCounts[key] =
    (issueCounts[key] ?? 0) + 1;
}


const duplicateIssueKeys =
  Object.entries(issueCounts)
    .filter(
      ([_, count]) => count > 1
    )
    .map(
      ([key]) => key
    );


if (duplicateIssueKeys.length > 0) {

  throw new Error(
    `Global Final Cluster 中发现重复 Issue：` +
    duplicateIssueKeys.join(", ")
  );
}


// ------------------------------------------------------------
// 12. 最终输出
// ------------------------------------------------------------

return results;

// ============================================================
// Build - Consolidation Input
//
// 输入：Parse Clustering Result 输出的第一阶段 Cluster
// 辅助数据：IF - Parse Success 输出的 118 个成功 Issue
//
// 输出：1 个 item
//      其中包含所有第一阶段 Cluster，供后续
//      Global Cluster Consolidation V1 一次性比较
// ============================================================


// ------------------------------------------------------------
// 1. 获取第一阶段 Cluster
// ------------------------------------------------------------

const clusterItems = $input.all();


// ------------------------------------------------------------
// 2. 获取原始成功 Issue
// ------------------------------------------------------------

const issueItems = $items("IF - Parse Success", 0);


// ------------------------------------------------------------
// 3. 基础检查
// ------------------------------------------------------------

if (clusterItems.length === 0) {
  throw new Error("没有收到任何第一阶段 Cluster");
}

if (issueItems.length === 0) {
  throw new Error("没有读取到 IF - Parse Success 的 Issue 数据");
}


// ------------------------------------------------------------
// 4. 建立 issue_key → Issue 数据映射
//
// 上游 Issue 没有单独保存 issue_key 时，
// 按原来的规则：source_comment_id + issue_index
// ------------------------------------------------------------

const issueMap = new Map();

for (const item of issueItems) {

  const data = item.json ?? {};

  let issueKey = null;

  if (
    data.source_comment_id != null &&
    data.issue_index != null
  ) {
    issueKey =
      `${data.source_comment_id}__${data.issue_index}`;
  }

  if (!issueKey) {
    continue;
  }

  if (issueMap.has(issueKey)) {
    throw new Error(
      `发现重复 issue_key：${issueKey}`
    );
  }

  issueMap.set(issueKey, data);
}


// ------------------------------------------------------------
// 5. 文本去重辅助函数
// ------------------------------------------------------------

function uniqueNonEmpty(values) {

  const seen = new Set();
  const result = [];

  for (const value of values) {

    const text =
      String(value ?? "").trim();

    if (!text) {
      continue;
    }

    if (seen.has(text)) {
      continue;
    }

    seen.add(text);
    result.push(text);
  }

  return result;
}


// ------------------------------------------------------------
// 6. 整理所有第一阶段 Cluster
// ------------------------------------------------------------

const clusters = [];

const seenClusterIds = new Set();

const allClusterIssueKeys = [];


// ------------------------------------------------------------
// 每个 Cluster 最多提供 3 条语义证据给第二阶段。
// 不需要把完整评论重新塞进去。
// ------------------------------------------------------------

const MAX_EVIDENCE_PER_CLUSTER = 3;


for (const item of clusterItems) {

  const cluster = item.json ?? {};


  // ----------------------------------------------------------
  // 第一阶段必须已经成功
  // ----------------------------------------------------------

  if (cluster.parse_status !== "success") {

    throw new Error(
      `发现未成功的第一阶段 Cluster：` +
      `${cluster.group_id ?? "unknown"}，` +
      `parse_error=${cluster.parse_error ?? "unknown"}`
    );
  }


  // ----------------------------------------------------------
  // Cluster ID 检查
  // ----------------------------------------------------------

  const clusterId =
    String(cluster.cluster_id ?? "").trim();

  if (!clusterId) {
    throw new Error("发现 cluster_id 为空的 Cluster");
  }

  if (seenClusterIds.has(clusterId)) {
    throw new Error(
      `发现重复 cluster_id：${clusterId}`
    );
  }

  seenClusterIds.add(clusterId);


  // ----------------------------------------------------------
  // Cluster Name 检查
  // ----------------------------------------------------------

  const clusterName =
    String(cluster.cluster_name ?? "").trim();

  if (!clusterName) {
    throw new Error(
      `Cluster ${clusterId} 的 cluster_name 为空`
    );
  }


  // ----------------------------------------------------------
  // 成员 Issue
  // ----------------------------------------------------------

  const memberIssueKeys =
    Array.isArray(cluster.member_issue_keys)
      ? cluster.member_issue_keys
      : [];

  if (memberIssueKeys.length === 0) {
    throw new Error(
      `Cluster ${clusterId} 没有 member_issue_keys`
    );
  }


  allClusterIssueKeys.push(
    ...memberIssueKeys
  );


  // ----------------------------------------------------------
  // 找回这个 Cluster 对应的 Issue 语义信息
  // ----------------------------------------------------------

  const memberIssues = [];

  const missingIssueKeys = [];


  for (const issueKey of memberIssueKeys) {

    const issue =
      issueMap.get(issueKey);

    if (!issue) {

      missingIssueKeys.push(
        issueKey
      );

      continue;
    }

    memberIssues.push({
      issue_key:
        issueKey,

      summary:
        String(
          issue.summary ?? ""
        ).trim(),

      user_need:
        String(
          issue.user_need ?? ""
        ).trim()
    });
  }


  // ----------------------------------------------------------
  // 如果 Cluster 引用了不存在的 Issue，直接报错
  // ----------------------------------------------------------

  if (missingIssueKeys.length > 0) {

    throw new Error(
      `Cluster ${clusterId} 找不到以下 Issue：` +
      missingIssueKeys.join(", ")
    );
  }


  // ----------------------------------------------------------
  // 提取去重后的 summary / user_need
  // ----------------------------------------------------------

  const summaries =
    uniqueNonEmpty(
      memberIssues.map(
        issue => issue.summary
      )
    );


  const userNeeds =
    uniqueNonEmpty(
      memberIssues.map(
        issue => issue.user_need
      )
    );


  // ----------------------------------------------------------
  // 最多保留 3 个 evidence example
  //
  // 目的：
  // 第二阶段需要语义证据，
  // 但不重新发送所有完整评论。
  // ----------------------------------------------------------

  const evidenceExamples =
    memberIssues
      .slice(
        0,
        MAX_EVIDENCE_PER_CLUSTER
      )
      .map(issue => ({
        summary:
          issue.summary,

        user_need:
          issue.user_need
      }));


  // ----------------------------------------------------------
  // 构造一个待 Consolidation 的 Cluster
  // ----------------------------------------------------------

  clusters.push({

    cluster_id:
      clusterId,

    source_group_id:
      cluster.group_id ?? null,

    category:
      cluster.category ?? null,

    feature:
      cluster.feature ?? null,

    cluster_name:
      clusterName,

    member_count:
      memberIssueKeys.length,

    // 这个字段主要供后续 Parse / 合并代码使用，
    // 不一定需要全部发送给 LLM。
    member_issue_keys:
      memberIssueKeys,

    // 第二层语义判断辅助信息
    summaries:
      summaries,

    user_needs:
      userNeeds,

    evidence_examples:
      evidenceExamples
  });
}


// ------------------------------------------------------------
// 7. 全局 Issue 完整性检查
//
// 第一阶段的所有 Cluster 加起来，
// 应覆盖 118 个成功 Issue，且每个只能出现一次。
// ------------------------------------------------------------

const keyCounts = {};

for (const key of allClusterIssueKeys) {

  keyCounts[key] =
    (keyCounts[key] ?? 0) + 1;
}


// 重复分配
const duplicateIssueKeys =
  Object.entries(keyCounts)
    .filter(
      ([_, count]) => count > 1
    )
    .map(
      ([key]) => key
    );


// Cluster 中实际出现的 Issue
const clusterIssueSet =
  new Set(allClusterIssueKeys);


// 原始成功 Issue
const sourceIssueKeys =
  Array.from(issueMap.keys());


// 缺失 Issue
const missingIssueKeys =
  sourceIssueKeys.filter(
    key => !clusterIssueSet.has(key)
  );


// 多出来的 Issue
const extraIssueKeys =
  allClusterIssueKeys.filter(
    key => !issueMap.has(key)
  );


// ------------------------------------------------------------
// 8. 如果完整性有问题，不继续做第二阶段
// ------------------------------------------------------------

if (
  duplicateIssueKeys.length > 0 ||
  missingIssueKeys.length > 0 ||
  extraIssueKeys.length > 0
) {

  throw new Error(
    [
      "第一阶段 Cluster 全局完整性检查失败",
      `missing=${missingIssueKeys.length}`,
      `duplicate=${duplicateIssueKeys.length}`,
      `extra=${extraIssueKeys.length}`
    ].join(" | ")
  );
}


// ------------------------------------------------------------
// 9. 输出一个 item
// ------------------------------------------------------------

return [
  {
    json: {

      consolidation_input_version:
        "v1",

      first_stage_cluster_count:
        clusters.length,

      total_issue_count:
        sourceIssueKeys.length,

      total_cluster_issue_refs:
        allClusterIssueKeys.length,

      validation_status:
        "success",

      missing_issue_keys:
        [],

      duplicate_issue_keys:
        [],

      extra_issue_keys:
        [],

      clusters:
        clusters
    }
  }
];

// ==========================================
// Phase 6 - Sort Cluster Statistics
//
// 排序规则：
// 1. feedback_count 降序
// 2. avg_severity 降序
// 3. negative_rate_pct 降序
// 4. high_severity_rate_pct 降序
//
// 注意：
// 这里只是为了 Phase 6 人工检查。
// 这不是 Priority Score。
// Phase 7 会单独计算正式优先级。
// ==========================================

const items = $input.all();

const rows = items.map(item => ({
  ...item.json
}));

rows.sort((a, b) => {

  // 1. Feedback Count
  const feedbackA =
    Number(a.feedback_count ?? 0);

  const feedbackB =
    Number(b.feedback_count ?? 0);

  if (feedbackB !== feedbackA) {
    return feedbackB - feedbackA;
  }


  // 2. Average Severity
  const severityA =
    Number(a.avg_severity ?? 0);

  const severityB =
    Number(b.avg_severity ?? 0);

  if (severityB !== severityA) {
    return severityB - severityA;
  }


  // 3. Negative Rate
  const negativeA =
    Number(a.negative_rate_pct ?? 0);

  const negativeB =
    Number(b.negative_rate_pct ?? 0);

  if (negativeB !== negativeA) {
    return negativeB - negativeA;
  }


  // 4. High Severity Rate
  const highRateA =
    Number(a.high_severity_rate_pct ?? 0);

  const highRateB =
    Number(b.high_severity_rate_pct ?? 0);

  return highRateB - highRateA;
});


// 添加 QA 排序序号
return rows.map((row, index) => ({
  json: {
    phase6_sort_rank: index + 1,
    ...row
  }
}));

// ============================================================
// Issue Statistics - Final Cluster Version
//
// 输入：Merge - Final Clusters and Issues
//
// 输入中同时包含：
// 1. Final Cluster（约 58 条）
// 2. 原始成功 Issue（118 条）
//
// 功能：
// 1. 建立 issue_key → Issue 映射
// 2. 根据 Final Cluster 的 member_issue_keys 找回原始 Issue
// 3. 计算 Frequency / Severity / Sentiment
// 4. 选代表性评论
// 5. 检查 118 个 Issue 是否全部且只被使用一次
//
// 输出：每个 Final Cluster 1 item
// ============================================================


// ------------------------------------------------------------
// 1. 获取 Merge 后所有输入
// ------------------------------------------------------------

const allItems = $input.all();

if (allItems.length === 0) {
  throw new Error("Issue Statistics 没有收到任何输入");
}


// ------------------------------------------------------------
// 2. 区分 Final Cluster 和原始 Issue
// ------------------------------------------------------------

const finalClusterItems = [];
const issueItems = [];

for (const item of allItems) {

  const data = item.json ?? {};

  // Final Cluster
  if (data.final_cluster_id) {

    finalClusterItems.push(data);
    continue;
  }

  // 原始 Issue
  if (
    data.issue_key ||
    (
      data.source_comment_id != null &&
      data.issue_index != null
    )
  ) {

    issueItems.push(data);
  }
}


if (finalClusterItems.length === 0) {
  throw new Error(
    "没有识别到 Final Cluster，请检查 Parse Global Consolidation → Merge 连线"
  );
}

if (issueItems.length === 0) {
  throw new Error(
    "没有识别到原始 Issue，请检查 IF - Parse Success → Merge 连线"
  );
}


// ------------------------------------------------------------
// 3. 辅助函数
// ------------------------------------------------------------

function getIssueKey(issue) {

  // 优先使用已经存在的 issue_key
  const existing =
    String(issue.issue_key ?? "").trim();

  if (existing) {
    return existing;
  }

  // 否则使用 source_comment_id + issue_index
  if (
    issue.source_comment_id != null &&
    issue.issue_index != null
  ) {

    return (
      String(issue.source_comment_id).trim()
      + "__"
      + String(issue.issue_index).trim()
    );
  }

  return null;
}


function getFeedbackId(issueKey, issue) {

  // 优先从 issue_key 取，
  // 避免超长 source_comment_id 被 JS 数字精度影响
  if (issueKey && issueKey.includes("__")) {

    return issueKey.split("__")[0];
  }

  if (issue.source_comment_id != null) {

    return String(
      issue.source_comment_id
    ).trim();
  }

  return null;
}


function toNumber(value) {

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return null;
  }

  const num = Number(value);

  return Number.isFinite(num)
    ? num
    : null;
}


function normalizeSentiment(value) {

  const text =
    String(value ?? "")
      .trim()
      .toLowerCase();

  if (
    text === "negative" ||
    text.includes("负向") ||
    text.includes("负面")
  ) {
    return "negative";
  }

  if (
    text === "positive" ||
    text.includes("正向") ||
    text.includes("正面")
  ) {
    return "positive";
  }

  if (
    text === "neutral" ||
    text.includes("中性")
  ) {
    return "neutral";
  }

  return "unknown";
}


function getContent(issue) {

  const candidates = [
    issue.content,
    issue.comment_content,
    issue.review_content,
    issue.original_content,
    issue.raw_content
  ];

  for (const value of candidates) {

    const text =
      String(value ?? "").trim();

    if (text) {
      return text;
    }
  }

  // 实在没有原评论时，
  // 最后才退化为 summary
  return String(
    issue.summary ?? ""
  ).trim();
}


function round(value, digits = 4) {

  if (!Number.isFinite(value)) {
    return null;
  }

  const factor =
    Math.pow(10, digits);

  return (
    Math.round(value * factor)
    / factor
  );
}


// ------------------------------------------------------------
// 4. 建立 issue_key → Issue Map
// ------------------------------------------------------------

const issueMap = new Map();

for (const issue of issueItems) {

  const issueKey =
    getIssueKey(issue);

  if (!issueKey) {

    throw new Error(
      "发现无法生成 issue_key 的原始 Issue"
    );
  }

  if (issueMap.has(issueKey)) {

    throw new Error(
      `原始 Issue 中存在重复 issue_key：${issueKey}`
    );
  }

  issueMap.set(
    issueKey,
    issue
  );
}


// ------------------------------------------------------------
// 5. 计算全局唯一 Feedback 数
//
// 注意：
// 一个评论可能拆成多个 Issue，
// Frequency 应按原评论数计算，而不是 Issue 数。
// ------------------------------------------------------------

const globalFeedbackIds =
  new Set();

for (
  const [issueKey, issue]
  of issueMap.entries()
) {

  const feedbackId =
    getFeedbackId(
      issueKey,
      issue
    );

  if (feedbackId) {

    globalFeedbackIds.add(
      feedbackId
    );
  }
}


const totalFeedbackCount =
  globalFeedbackIds.size;

const totalIssueCount =
  issueMap.size;

const totalFinalClusterCount =
  finalClusterItems.length;


// ------------------------------------------------------------
// 6. Global Cluster 完整性检查
// ------------------------------------------------------------

const allMemberIssueKeys = [];

for (const cluster of finalClusterItems) {

  const members =
    Array.isArray(
      cluster.member_issue_keys
    )
      ? cluster.member_issue_keys
      : [];

  if (members.length === 0) {

    throw new Error(
      `Final Cluster ${cluster.final_cluster_id} 没有 member_issue_keys`
    );
  }

  allMemberIssueKeys.push(
    ...members
  );
}


// 每个 Issue 被引用多少次
const globalMemberCounts = {};

for (const issueKey of allMemberIssueKeys) {

  globalMemberCounts[issueKey] =
    (globalMemberCounts[issueKey] ?? 0)
    + 1;
}


// 重复引用
const duplicateIssueKeys =
  Object.entries(
    globalMemberCounts
  )
    .filter(
      ([_, count]) => count > 1
    )
    .map(
      ([key]) => key
    );


// Cluster 引用了不存在的 Issue
const extraIssueKeys =
  allMemberIssueKeys.filter(
    key => !issueMap.has(key)
  );


// 原始 Issue 没有进入任何 Final Cluster
const finalMemberSet =
  new Set(
    allMemberIssueKeys
  );

const missingIssueKeys =
  Array.from(
    issueMap.keys()
  ).filter(
    key =>
      !finalMemberSet.has(key)
  );


if (
  duplicateIssueKeys.length > 0 ||
  extraIssueKeys.length > 0 ||
  missingIssueKeys.length > 0
) {

  throw new Error(
    [
      "Final Cluster → Issue 全局完整性检查失败",
      `missing=${missingIssueKeys.length}`,
      `duplicate=${duplicateIssueKeys.length}`,
      `extra=${extraIssueKeys.length}`
    ].join(" | ")
  );
}


// ------------------------------------------------------------
// 7. 对每个 Final Cluster 计算统计
// ------------------------------------------------------------

const results = [];


for (const cluster of finalClusterItems) {

  const clusterId =
    String(
      cluster.final_cluster_id ?? ""
    ).trim();

  const clusterName =
    String(
      cluster.final_cluster_name ?? ""
    ).trim();


  if (!clusterId) {

    throw new Error(
      "发现 final_cluster_id 为空"
    );
  }


  if (!clusterName) {

    throw new Error(
      `${clusterId} 的 final_cluster_name 为空`
    );
  }


  const memberIssueKeys =
    Array.isArray(
      cluster.member_issue_keys
    )
      ? cluster.member_issue_keys
      : [];


  // ----------------------------------------------------------
  // 找回该 Cluster 的所有 Issue
  // ----------------------------------------------------------

  const memberIssues = [];

  for (const issueKey of memberIssueKeys) {

    const issue =
      issueMap.get(issueKey);

    if (!issue) {

      throw new Error(
        `${clusterId} 找不到 Issue：${issueKey}`
      );
    }

    memberIssues.push({
      ...issue,

      _issue_key:
        issueKey,

      _feedback_id:
        getFeedbackId(
          issueKey,
          issue
        ),

      _severity:
        toNumber(
          issue.severity
        ),

      _sentiment:
        normalizeSentiment(
          issue.sentiment
        ),

      _content:
        getContent(
          issue
        )
    });
  }


  // ----------------------------------------------------------
  // 8. Frequency
  //
  // issue_count:
  // Cluster 中共有多少 Issue
  //
  // feedback_count:
  // 有多少条唯一原评论
  // ----------------------------------------------------------

  const issueCount =
    memberIssues.length;


  const clusterFeedbackIds =
    new Set(
      memberIssues
        .map(
          issue => issue._feedback_id
        )
        .filter(Boolean)
    );


  const feedbackCount =
    clusterFeedbackIds.size;


  const feedbackShare =
    totalFeedbackCount > 0
      ? feedbackCount
        / totalFeedbackCount
      : 0;


  const feedbackSharePct =
    feedbackShare * 100;


  // ----------------------------------------------------------
  // 9. Severity
  // ----------------------------------------------------------

  const severities =
    memberIssues
      .map(
        issue => issue._severity
      )
      .filter(
        value =>
          Number.isFinite(value)
      );


  const avgSeverity =
    severities.length > 0
      ? severities.reduce(
          (sum, value) =>
            sum + value,
          0
        )
        / severities.length
      : null;


  const maxSeverity =
    severities.length > 0
      ? Math.max(...severities)
      : null;


  const highSeverityCount =
    severities.filter(
      value => value >= 4
    ).length;


  const highSeverityRate =
    severities.length > 0
      ? highSeverityCount
        / severities.length
      : 0;


  let severityLevel =
    "low";


  if (
    avgSeverity !== null &&
    avgSeverity >= 4
  ) {

    severityLevel =
      "high";

  } else if (
    avgSeverity !== null &&
    avgSeverity >= 2.5
  ) {

    severityLevel =
      "medium";
  }


  // ----------------------------------------------------------
  // 10. Sentiment
  // ----------------------------------------------------------

  let negativeCount = 0;
  let neutralCount = 0;
  let positiveCount = 0;
  let unknownSentimentCount = 0;


  for (const issue of memberIssues) {

    switch (
      issue._sentiment
    ) {

      case "negative":
        negativeCount++;
        break;

      case "neutral":
        neutralCount++;
        break;

      case "positive":
        positiveCount++;
        break;

      default:
        unknownSentimentCount++;
    }
  }


  const sentimentBase =
    memberIssues.length;


  const negativeRate =
    sentimentBase > 0
      ? negativeCount
        / sentimentBase
      : 0;


  const neutralRate =
    sentimentBase > 0
      ? neutralCount
        / sentimentBase
      : 0;


  const positiveRate =
    sentimentBase > 0
      ? positiveCount
        / sentimentBase
      : 0;


  // ----------------------------------------------------------
  // 11. Representative Comment
  //
  // 排序优先级：
  // ① Severity 高
  // ② Negative 优先
  // ③ 原评论信息量更长
  // ----------------------------------------------------------

  const representativeCandidates =
    [...memberIssues]
      .sort((a, b) => {

        const severityA =
          a._severity ?? -1;

        const severityB =
          b._severity ?? -1;


        if (
          severityB !== severityA
        ) {

          return (
            severityB
            - severityA
          );
        }


        const negativeA =
          a._sentiment ===
          "negative"
            ? 1
            : 0;

        const negativeB =
          b._sentiment ===
          "negative"
            ? 1
            : 0;


        if (
          negativeB !== negativeA
        ) {

          return (
            negativeB
            - negativeA
          );
        }


        return (
          String(
            b._content ?? ""
          ).length
          -
          String(
            a._content ?? ""
          ).length
        );
      });


  const representative =
    representativeCandidates[0]
    ?? null;


  // ----------------------------------------------------------
  // 12. 输出 Cluster Statistics
  // ----------------------------------------------------------

  results.push({

    json: {

      // ---------------------------
      // Final Cluster
      // ---------------------------

      final_cluster_id:
        clusterId,

      final_cluster_name:
        clusterName,


      source_cluster_ids:
        cluster.source_cluster_ids
        ?? [],

      source_cluster_count:
        cluster.source_cluster_count
        ?? (
          Array.isArray(
            cluster.source_cluster_ids
          )
            ? cluster
                .source_cluster_ids
                .length
            : null
        ),


      source_cluster_names:
        cluster.source_cluster_names
        ?? [],


      source_categories:
        cluster.source_categories
        ?? [],

      source_features:
        cluster.source_features
        ?? [],


      // ---------------------------
      // Frequency
      // ---------------------------

      issue_count:
        issueCount,

      feedback_count:
        feedbackCount,

      feedback_share:
        round(
          feedbackShare,
          4
        ),

      feedback_share_pct:
        round(
          feedbackSharePct,
          2
        ),


      // ---------------------------
      // Severity
      // ---------------------------

      avg_severity:
        avgSeverity === null
          ? null
          : round(
              avgSeverity,
              2
            ),

      max_severity:
        maxSeverity,

      severity_level:
        severityLevel,

      high_severity_count:
        highSeverityCount,

      high_severity_rate:
        round(
          highSeverityRate,
          4
        ),

      high_severity_rate_pct:
        round(
          highSeverityRate * 100,
          2
        ),


      // ---------------------------
      // Sentiment
      // ---------------------------

      negative_count:
        negativeCount,

      neutral_count:
        neutralCount,

      positive_count:
        positiveCount,

      unknown_sentiment_count:
        unknownSentimentCount,


      negative_rate:
        round(
          negativeRate,
          4
        ),

      neutral_rate:
        round(
          neutralRate,
          4
        ),

      positive_rate:
        round(
          positiveRate,
          4
        ),


      negative_rate_pct:
        round(
          negativeRate * 100,
          2
        ),

      neutral_rate_pct:
        round(
          neutralRate * 100,
          2
        ),

      positive_rate_pct:
        round(
          positiveRate * 100,
          2
        ),


      // ---------------------------
      // Representative Feedback
      // ---------------------------

      representative_issue_key:
        representative
          ? representative._issue_key
          : null,

      representative_feedback_id:
        representative
          ? representative._feedback_id
          : null,

      representative_comment:
        representative
          ? representative._content
          : null,

      representative_summary:
        representative
          ? (
              representative.summary
              ?? null
            )
          : null,

      representative_user_need:
        representative
          ? (
              representative.user_need
              ?? null
            )
          : null,

      representative_severity:
        representative
          ? representative._severity
          : null,

      representative_sentiment:
        representative
          ? representative._sentiment
          : null,


      // ---------------------------
      // Member Traceability
      // ---------------------------

      member_issue_keys:
        memberIssueKeys,


      // ---------------------------
      // Global QA
      // ---------------------------

      total_final_cluster_count:
        totalFinalClusterCount,

      total_issue_count:
        totalIssueCount,

      total_feedback_count:
        totalFeedbackCount,

      total_cluster_issue_refs:
        allMemberIssueKeys.length,


      global_validation_status:
        "success",

      global_missing_issue_count:
        0,

      global_duplicate_issue_count:
        0,

      global_extra_issue_count:
        0,


      // ---------------------------
      // Version
      // ---------------------------

      clustering_stage:
        "final_global_consolidation",

      issue_clustering_prompt_version:
        "v2",

      global_consolidation_prompt_version:
        "v1"
    }
  });
}


// ------------------------------------------------------------
// 13. 输出
// ------------------------------------------------------------

return results;

const aiItems = $input.all();

// 现在已经删除 IF - Need Clustering，
// 所有 Group 都直接进入 DeepSeek，
// 所以这里直接从 Group Issues by Category Feature
// 读取原始分组数据。
const sourceItems = $items("Group Issues by Category Feature", 0);

const results = [];


// ==========================================
// 0. 基础数量检查
// ==========================================
//
// 理论上：
// 一个 Group → 一次 DeepSeek 调用 → 一个 AI 输出
//
// 所以两边数量必须一致。
// 如果不一致，直接报错，避免后面错位匹配。
// ==========================================

if (aiItems.length !== sourceItems.length) {
  throw new Error(
    `DeepSeek 输出数量与原始 Group 数量不一致：` +
    `AI=${aiItems.length}, Source=${sourceItems.length}`
  );
}


// ==========================================
// 1. 逐个 Group 解析 AI 返回结果
// ==========================================

for (let i = 0; i < aiItems.length; i++) {

  const ai = aiItems[i].json;
  const source = sourceItems[i]?.json ?? {};


  // ----------------------------------------
  // 原始 Group 信息
  // ----------------------------------------

  const groupId =
    source.group_id ??
    `G${String(i + 1).padStart(3, "0")}`;

  const category =
    source.category ?? null;

  const feature =
    source.feature ?? null;


  // ----------------------------------------
  // 当前 Group 的原始 Issue
  // ----------------------------------------

  const inputIssues =
    Array.isArray(source.issues)
      ? source.issues
      : [];


  const inputIssueKeys =
    inputIssues
      .map(issue => issue.issue_key)
      .filter(Boolean);


  // ========================================
  // 2. 提取 DeepSeek 返回内容
  // ========================================

  let rawContent =
    ai?.choices?.[0]?.message?.content ?? "";


  // 去掉可能出现的 Markdown code fence
  rawContent =
    String(rawContent)
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();


  const finishReason =
    ai?.choices?.[0]?.finish_reason ?? null;


  // ========================================
  // 3. JSON Parse
  // ========================================

  let parsed = null;
  let parseError = null;


  try {

    parsed =
      JSON.parse(rawContent);

  } catch (error) {

    parseError =
      error.message;

  }


  // ========================================
  // 4. JSON 解析失败
  // ========================================

  if (!parsed) {

    results.push({

      json: {

        group_id:
          groupId,

        category:
          category,

        feature:
          feature,


        cluster_id:
          null,

        cluster_name:
          null,

        member_issue_keys:
          [],

        member_count:
          0,


        clustering_method:
          "llm_group_clustering",

        clustering_prompt_version:
          "v2",

        clustering_model:
          ai.model ?? null,


        finish_reason:
          finishReason,

        raw_ai_content:
          rawContent,


        missing_issue_keys:
          inputIssueKeys,

        extra_issue_keys:
          [],

        duplicate_issue_keys:
          [],


        parse_status:
          "failed",

        parse_error:
          parseError ?? "JSON解析失败"

      }

    });


    continue;
  }


  // ========================================
  // 5. clusters 不存在或为空
  // ========================================

  if (
    !Array.isArray(parsed.clusters) ||
    parsed.clusters.length === 0
  ) {

    results.push({

      json: {

        group_id:
          groupId,

        category:
          category,

        feature:
          feature,


        cluster_id:
          null,

        cluster_name:
          null,

        member_issue_keys:
          [],

        member_count:
          0,


        clustering_method:
          "llm_group_clustering",

        clustering_prompt_version:
          "v2",

        clustering_model:
          ai.model ?? null,


        finish_reason:
          finishReason,

        raw_ai_content:
          rawContent,


        missing_issue_keys:
          inputIssueKeys,

        extra_issue_keys:
          [],

        duplicate_issue_keys:
          [],


        parse_status:
          "failed",

        parse_error:
          "clusters 不存在、不是数组或数组为空"

      }

    });


    continue;
  }


  // ========================================
  // 6. 收集模型输出的所有 Issue Key
  // ========================================

  const outputIssueKeys = [];


  for (const cluster of parsed.clusters) {

    const members =
      Array.isArray(cluster.member_issue_keys)
        ? cluster.member_issue_keys
        : [];


    outputIssueKeys.push(
      ...members
    );
  }


  // ========================================
  // 7. Issue 分配完整性检查
  // ========================================

  const inputSet =
    new Set(inputIssueKeys);

  const outputSet =
    new Set(outputIssueKeys);


  // ----------------------------------------
  // A. Missing
  //
  // 输入有，但模型没输出
  // ----------------------------------------

  const missingKeys =
    inputIssueKeys.filter(
      key => !outputSet.has(key)
    );


  // ----------------------------------------
  // B. Extra
  //
  // 模型凭空生成了不存在的 issue_key
  // ----------------------------------------

  const extraKeys =
    outputIssueKeys.filter(
      key => !inputSet.has(key)
    );


  // ----------------------------------------
  // C. Duplicate
  //
  // 同一个 issue_key 被分到多个 Cluster
  // ----------------------------------------

  const keyCounts = {};


  for (const key of outputIssueKeys) {

    keyCounts[key] =
      (keyCounts[key] ?? 0) + 1;

  }


  const duplicateKeys =
    Object.entries(keyCounts)
      .filter(
        ([_, count]) => count > 1
      )
      .map(
        ([key]) => key
      );


  // ========================================
  // 8. 完整性检查失败
  // ========================================

  if (
    missingKeys.length > 0 ||
    extraKeys.length > 0 ||
    duplicateKeys.length > 0
  ) {

    results.push({

      json: {

        group_id:
          groupId,

        category:
          category,

        feature:
          feature,


        cluster_id:
          null,

        cluster_name:
          null,

        member_issue_keys:
          [],

        member_count:
          0,


        clustering_method:
          "llm_group_clustering",

        clustering_prompt_version:
          "v2",

        clustering_model:
          ai.model ?? null,


        finish_reason:
          finishReason,

        raw_ai_content:
          rawContent,


        missing_issue_keys:
          missingKeys,

        extra_issue_keys:
          extraKeys,

        duplicate_issue_keys:
          duplicateKeys,


        parse_status:
          "failed",

        parse_error:
          "Issue分配完整性检查失败"

      }

    });


    continue;
  }


  // ========================================
  // 9. 正常展开 Cluster
  // ========================================

  for (
    let j = 0;
    j < parsed.clusters.length;
