const aiItems = $input.all();
const sourceBatches = $items("Build Analyzer Batches");
const results = [];

if (aiItems.length !== sourceBatches.length) {
  throw new Error(`ANALYZER_BATCH_COUNT_MISMATCH: responses=${aiItems.length}, batches=${sourceBatches.length}`);
}

for (let batchIndex = 0; batchIndex < aiItems.length; batchIndex++) {
  const ai = aiItems[batchIndex].json ?? {};
  const batch = sourceBatches[batchIndex]?.json ?? {};
  const reviews = batch.reviews;
  const raw = ai?.choices?.[0]?.message?.content;
  const finishReason = ai?.choices?.[0]?.finish_reason ?? null;

  if (!Array.isArray(reviews) || reviews.length === 0) {
    throw new Error(`ANALYZER_BATCH_SOURCE_INVALID: batch ${batchIndex + 1}`);
  }
  if (typeof raw !== "string" || !raw.trim()) {
    throw new Error(`ANALYZER_BATCH_EMPTY_RESPONSE: batch ${batchIndex + 1}`);
  }
  if (finishReason !== "stop") {
    throw new Error(`ANALYZER_BATCH_INCOMPLETE_RESPONSE: batch ${batchIndex + 1}, finish_reason=${finishReason}`);
  }

  const cleaned = raw.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`ANALYZER_BATCH_JSON_PARSE_FAILED: batch ${batchIndex + 1}: ${error.message}`);
  }

  if (!parsed || !Array.isArray(parsed.results) || parsed.results.length !== reviews.length) {
    throw new Error(`ANALYZER_BATCH_RESULT_COUNT_INVALID: batch ${batchIndex + 1}`);
  }

  const expectedIds = new Set(reviews.map(row => String(row.batch_item_id)));
  const byId = new Map();
  for (const row of parsed.results) {
    const id = String(row?.batch_item_id ?? "");
    if (!id || !expectedIds.has(id) || byId.has(id)) {
      throw new Error(`ANALYZER_BATCH_ID_INVALID_OR_DUPLICATED: ${id || "<empty>"}`);
    }
    if (!Array.isArray(row.issues) || row.issues.length === 0) {
      throw new Error(`ANALYZER_BATCH_ISSUES_EMPTY: ${id}`);
    }
    byId.set(id, row);
  }

  if (byId.size !== expectedIds.size) {
    throw new Error(`ANALYZER_BATCH_MISSING_RESULT: batch ${batchIndex + 1}`);
  }

  for (const source of reviews) {
    const parsedRow = byId.get(String(source.batch_item_id));
    for (let issueIndex = 0; issueIndex < parsedRow.issues.length; issueIndex++) {
      const issue = parsedRow.issues[issueIndex];
      if (!issue || typeof issue !== "object" || Array.isArray(issue)) {
        throw new Error(`ANALYZER_BATCH_ISSUE_INVALID: ${source.batch_item_id} #${issueIndex + 1}`);
      }
      const required = ["category", "feature", "sentiment", "severity", "user_need", "summary", "confidence"];
      for (const field of required) {
        if (!(field in issue) || issue[field] === null || issue[field] === undefined) {
          throw new Error(`ANALYZER_BATCH_ISSUE_FIELD_MISSING: ${source.batch_item_id} ${field}`);
        }
      }

      results.push({
        json: {
          source_comment_id: source.source_comment_id ?? null,
          content: source.content ?? "",
          rating: source.rating ?? null,
          review_date: source.review_date ?? null,
          source: source.source ?? "应用宝",
          app_version: source.app_version ?? null,
          issue_index: issueIndex + 1,
          category: issue.category,
          feature: issue.feature,
          sentiment: issue.sentiment,
          severity: issue.severity,
          user_need: issue.user_need,
          summary: issue.summary,
          confidence: issue.confidence,
          analyzer_prompt_version: "v2",
          analyzer_model: ai.model ?? "deepseek-flash",
          finish_reason: finishReason,
          parse_status: "success",
          parse_error: null
        }
      });
    }
  }
}

return results;

