function formatShanghaiTime(unixSeconds) {
  if (!unixSeconds) return null;

  const date = new Date(unixSeconds * 1000);

  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Shanghai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).formatToParts(date);

  const map = {};

  for (const part of parts) {
    map[part.type] = part.value;
  }

  return `${map.year}-${map.month}-${map.day} ${map.hour}:${map.minute}:${map.second}`;
}

for (const input of inputs) {
  const components = input.json?.data?.components ?? [];

  for (const component of components) {
    const itemData = component?.data?.itemData ?? [];

    for (const item of itemData) {
      const comment = item.comment ?? {};

      results.push({
        json: {
          source_comment_id: comment.commentID ?? null,
          content: comment.content ?? "",
          rating: comment.mulDimensionScore?.total ?? null,
          review_date: formatShanghaiTime(comment.createTime),
          source: "应用宝",
          app_version: null
        }
      });
    }
  }
}

return results;

const sourceItems = $input.all();
