for (let start = 0; start < sourceItems.length; start += BATCH_SIZE) {
  const slice = sourceItems.slice(start, start + BATCH_SIZE);
  const reviews = slice.map((item, offset) => {
    const row = item.json ?? {};
    const sourceId = row.source_comment_id ?? null;
    const normalizedId = String(sourceId ?? "").trim();
    const batchItemId = normalizedId
      ? `comment:${normalizedId}`
      : `row:${start + offset + 1}`;

    if (seen.has(batchItemId)) {
      throw new Error(`Duplicate batch_item_id in quality input: ${batchItemId}`);
    }
    seen.add(batchItemId);

    return {
      batch_item_id: batchItemId,
      source_comment_id: sourceId,
      content: String(row.content ?? ""),
      rating: row.rating ?? null,
      review_date: row.review_date ?? null,
      source: row.source ?? "应用宝",
      app_version: row.app_version ?? null
    };
  });

  output.push({
    json: {
      batch_index: output.length + 1,
      reviews
    }
  });
}

